/// `trap_Trace` helper: a point/box solid trace, faithfully passing NULL for
/// `mins`/`maxs` when the caller wants a point trace (Raven passes literal
/// `NULL`). Keeps every trace call site a one-liner.
#[inline]
unsafe fn wp_trace(
    ctx: GameContext<'_>,
    tr: *mut trace_t,
    start: &vec3_t,
    mins: *const vec3_t,
    maxs: *const vec3_t,
    end: &vec3_t,
    pass_ent: c_int,
    mask: c_int,
) {
    trap::Trace(
        ctx.engine,
        GTraceArgs::new(tr, start, mins, maxs, end, pass_ent, mask),
    );
}

/// Raven `GetFlagStr`.
///
/// Builds a human-readable waypoint-flag string into a `B_TempAlloc`'d
/// scratch buffer (128 bytes) — ports 1:1 as raw-pointer byte writes since
/// `B_TempAlloc`/`B_TempFree` are the (parked-elsewhere) allocator seam and
/// this function touches no file-scope globals itself.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:25-210`
pub fn GetFlagStr(
    ctx: GameContext<'_>,flags: c_int) -> *mut c_char {
    // Raven flag bit values (`ai_main.h:22-38`); not yet ported anywhere else
    // in the crate graph, so defined locally, verbatim.
    const WPFLAG_JUMP: c_int = 0x00000010;
    pub const WPFLAG_DUCK: c_int = 0x00000020;
    pub const WPFLAG_NOVIS: c_int = 0x00000400;
    pub const WPFLAG_SNIPEORCAMPSTAND: c_int = 0x00000800;
    pub const WPFLAG_WAITFORFUNC: c_int = 0x00001000;
    pub const WPFLAG_SNIPEORCAMP: c_int = 0x00002000;
    const WPFLAG_ONEWAY_FWD: c_int = 0x00004000;
    const WPFLAG_ONEWAY_BACK: c_int = 0x00008000;
    pub const WPFLAG_GOALPOINT: c_int = 0x00010000;
    const WPFLAG_RED_FLAG: c_int = 0x00020000;
    const WPFLAG_BLUE_FLAG: c_int = 0x00040000;
    pub const WPFLAG_SIEGE_REBELOBJ: c_int = 0x00080000;
    pub const WPFLAG_SIEGE_IMPERIALOBJ: c_int = 0x00100000;
    pub const WPFLAG_NOMOVEFUNC: c_int = 0x00200000;

    unsafe {
        let flagstr = B_TempAlloc(ctx, 128) as *mut c_char;
        let mut i: isize = 0;

        // Local helper mirroring the C `flagstr[i] = 'x'; i++;` idiom.
        macro_rules! put {
            ($c:expr) => {{
                *flagstr.offset(i) = $c as c_char;
                i += 1;
            }};
        }

        if flags == 0 {
            let s = b"none\0";
            for (n, b) in s.iter().enumerate() {
                *flagstr.offset(n as isize) = *b as c_char;
            }
            return flagstr;
        }

        if flags & WPFLAG_JUMP != 0 {
            put!(b'j');
        }
        if flags & WPFLAG_DUCK != 0 {
            put!(b'd');
        }
        if flags & WPFLAG_SNIPEORCAMPSTAND != 0 {
            put!(b'c');
        }
        if flags & WPFLAG_WAITFORFUNC != 0 {
            put!(b'f');
        }
        if flags & WPFLAG_SNIPEORCAMP != 0 {
            put!(b's');
        }
        if flags & WPFLAG_ONEWAY_FWD != 0 {
            put!(b'x');
        }
        if flags & WPFLAG_ONEWAY_BACK != 0 {
            put!(b'y');
        }
        if flags & WPFLAG_GOALPOINT != 0 {
            put!(b'g');
        }
        if flags & WPFLAG_NOVIS != 0 {
            put!(b'n');
        }
        if flags & WPFLAG_NOMOVEFUNC != 0 {
            put!(b'm');
        }

        if flags & WPFLAG_RED_FLAG != 0 {
            if i != 0 {
                put!(b' ');
            }
            for b in b"red flag" {
                put!(*b);
            }
        }

        if flags & WPFLAG_BLUE_FLAG != 0 {
            if i != 0 {
                put!(b' ');
            }
            for b in b"blue flag" {
                put!(*b);
            }
        }

        if flags & WPFLAG_SIEGE_IMPERIALOBJ != 0 {
            if i != 0 {
                put!(b' ');
            }
            for b in b"saga_imp" {
                put!(*b);
            }
        }

        if flags & WPFLAG_SIEGE_REBELOBJ != 0 {
            if i != 0 {
                put!(b' ');
            }
            for b in b"saga_reb" {
                put!(*b);
            }
        }

        *flagstr.offset(i) = 0;

        if i == 0 {
            let s = b"unknown\0";
            for (n, b) in s.iter().enumerate() {
                *flagstr.offset(n as isize) = *b as c_char;
            }
        }

        flagstr
    }
}

/// Raven `G_TestLine`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:212-222`
pub fn G_TestLine(
    ctx: GameContext<'_>,start: vec3_t, end: vec3_t, color: c_int, time: c_int) {
    let ev_testline = mp_bg::public::entity_event::entity_event_t::EV_TESTLINE as c_int;
    // `SVF_BROADCAST` (svflags #define) is not yet ported anywhere in the
    // crate graph; defined locally, verbatim.
    // Source: `oracle/oracle/codemp/game/g_public.h:20`
    const SVF_BROADCAST: c_int = 0x00000020;

    unsafe {
        let te = G_TempEntity(ctx, start, ev_testline);
        (*te).s.origin = start;
        (*te).s.origin2 = end;
        (*te).s.time2 = time;
        (*te).s.weapon = color;
        (*te).r.svFlags |= SVF_BROADCAST;
    }
}

/// Raven `BotWaypointRender`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:224-347`
pub fn BotWaypointRender(ctx: GameContext<'_>) {
    // `SVF_BROADCAST` (svflags #define), local per this file's convention
    // (cf. `G_TestLine`). Source: `oracle/oracle/codemp/game/g_public.h:20`
    const SVF_BROADCAST: c_int = 0x00000020;
    let ev_scoreplum = mp_bg::public::entity_event::entity_event_t::EV_SCOREPLUM as c_int;

    unsafe {
        let w = ctx.world;

        if (*w).globals.gBotEdit == 0.0 {
            return;
        }

        let mut bestindex: c_int = 0;

        'checkprint: {
            if (*w).globals.gWPRenderTime <= (*w).level.time as f32 {
                (*w).globals.gWPRenderTime = (*w).level.time as f32 + 100.0;

                let mut i = (*w).globals.gWPRenderedFrame;
                let inc_checker = (*w).globals.gWPRenderedFrame;

                while i < (*w).globals.gWPNum {
                    let p = (*w).globals.gWPArray.0[i as usize];
                    if !p.is_null() && (*p).inuse != 0 {
                        let plum = G_TempEntity(ctx, (*p).origin, ev_scoreplum);
                        (*plum).r.svFlags |= SVF_BROADCAST;
                        (*plum).s.time = i;

                        let mut n: c_int = 0;
                        while n < (*p).neighbornum {
                            let nb = (*p).neighbors[n as usize];
                            if nb.forceJumpTo != 0 && !(*w).globals.gWPArray.0[nb.num as usize].is_null()
                            {
                                let dest = (*w).globals.gWPArray.0[nb.num as usize];
                                G_TestLine(ctx, (*p).origin, (*dest).origin, 0x0000ff, 5000);
                            }
                            n += 1;
                        }

                        (*w).globals.gWPRenderedFrame += 1;
                    } else {
                        (*w).globals.gWPRenderedFrame = 0;
                        break;
                    }

                    if (i - inc_checker) > 4 {
                        break; // don't render too many at once
                    }
                    i += 1;
                }

                if i >= (*w).globals.gWPNum {
                    (*w).globals.gWPRenderTime = (*w).level.time as f32 + 1500.0; // wait a bit after we finish doing the whole trail
                    (*w).globals.gWPRenderedFrame = 0;
                }
            }

            // PORT-NOTE(cvar-placement): `bot_wp_info` is an `ai_wpnav.c`
            // file-scope `vmCvar_t` with no home in `GameCvars`/`GameGlobals`
            // yet; reached the same way `bot_wp_*` handles are referenced
            // elsewhere in this file (missing_symbols).
            if (*w).cvars.bot_wp_info.value == 0.0 {
                return;
            }

            let viewent: *mut gentity_t = &mut (*w).entities[0];

            if viewent.is_null() || (*viewent).client.is_null() {
                // client isn't in the game yet?
                return;
            }

            let mut bestdist: f32 = 256.0; // max distance for showing point info
            let mut gotbestindex = false;

            let mut i: c_int = 0;
            while i < (*w).globals.gWPNum {
                let p = (*w).globals.gWPArray.0[i as usize];
                if !p.is_null() && (*p).inuse != 0 {
                    let vo = (*((*viewent).client as *mut gclient_t)).ps.origin;
                    let a = [vo[0] - (*p).origin[0], vo[1] - (*p).origin[1], vo[2] - (*p).origin[2]];
                    let checkdist = VectorLength(a);

                    if checkdist < bestdist {
                        bestdist = checkdist;
                        bestindex = i;
                        gotbestindex = true;
                    }
                }
                i += 1;
            }

            if gotbestindex && bestindex != (*w).globals.gLastPrintedIndex {
                let p = (*w).globals.gWPArray.0[bestindex as usize];
                let flagstr = GetFlagStr(ctx, (*p).flags);
                (*w).globals.gLastPrintedIndex = bestindex;
                let flagstr_s = cstr_to_str(flagstr);
                let s = format!(
                    "^3Waypoint {}\nFlags - {} ({}) (w{})\nOrigin - ({} {} {})\n",
                    (*p).index,
                    (*p).flags,
                    flagstr_s,
                    (*p).weight,
                    (*p).origin[0] as c_int,
                    (*p).origin[1] as c_int,
                    (*p).origin[2] as c_int,
                );
                G_Printf(ctx, cstr(&s).as_ptr());
                // GetFlagStr allocates 128 bytes for this, if it's changed then obviously this must be as well
                B_TempFree(ctx, 128); // flagstr

                let plum = G_TempEntity(ctx, (*p).origin, ev_scoreplum);
                (*plum).r.svFlags |= SVF_BROADCAST;
                (*plum).s.time = bestindex; // render it once
            } else if !gotbestindex {
                (*w).globals.gLastPrintedIndex = -1;
            }
        }
    }
}

/// Raven `TransferWPData`.
///
/// Copies one waypoint slot onto another (reusing the `B_Alloc`'d memory).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:349-369`
pub fn TransferWPData(ctx: GameContext<'_>, from: c_int, to: c_int) {
    unsafe {
        let w = ctx.world;
        if (*w).globals.gWPArray.0[to as usize].is_null() {
            (*w).globals.gWPArray.0[to as usize] =
                B_Alloc(ctx, size_of::<wpobject_t>() as c_int) as *mut wpobject_t;
        }

        if (*w).globals.gWPArray.0[to as usize].is_null() {
            G_Printf(
                ctx,
                c"^1FATAL ERROR: Could not allocated memory for waypoint\n".as_ptr(),
            );
        }

        let from_p = (*w).globals.gWPArray.0[from as usize];
        let to_p = (*w).globals.gWPArray.0[to as usize];
        (*to_p).flags = (*from_p).flags;
        (*to_p).weight = (*from_p).weight;
        (*to_p).associated_entity = (*from_p).associated_entity;
        (*to_p).disttonext = (*from_p).disttonext;
        (*to_p).forceJumpTo = (*from_p).forceJumpTo;
        (*to_p).index = to;
        (*to_p).inuse = (*from_p).inuse;
        (*to_p).origin = (*from_p).origin;
    }
}

/// Raven `CreateNewWP`.
///
/// Appends a fresh waypoint at `gWPNum`. `origin` is only read (copied into the
/// slot), so it stays by-value (fork-9: keep-by-value when never written).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:371-401`
pub fn CreateNewWP(ctx: GameContext<'_>, origin: vec3_t, flags: c_int) {
    unsafe {
        let w = ctx.world;
        if (*w).globals.gWPNum >= MAX_WPARRAY_SIZE {
            if (*w).cvars.g_RMG.integer == 0 {
                G_Printf(ctx, c"^3Warning: Waypoint limit hit (%i)\n".as_ptr());
            }
            return;
        }

        let n = (*w).globals.gWPNum as usize;
        if (*w).globals.gWPArray.0[n].is_null() {
            (*w).globals.gWPArray.0[n] =
                B_Alloc(ctx, size_of::<wpobject_t>() as c_int) as *mut wpobject_t;
        }

        if (*w).globals.gWPArray.0[n].is_null() {
            G_Printf(ctx, c"^1ERROR: Could not allocated memory for waypoint\n".as_ptr());
        }

        let p = (*w).globals.gWPArray.0[n];
        (*p).flags = flags;
        (*p).weight = 0.0; // calculated elsewhere
        (*p).associated_entity = ENTITYNUM_NONE; // set elsewhere
        (*p).forceJumpTo = 0;
        (*p).disttonext = 0.0; // calculated elsewhere
        (*p).index = (*w).globals.gWPNum;
        (*p).inuse = 1;
        (*p).origin = origin;
        (*w).globals.gWPNum += 1;
    }
}

/// Raven `CreateNewWP_FromObject`.
///
/// Appends a waypoint copied from an in-memory `wpobject_t` (the load path),
/// carrying neighbours and re-latching the CTF flag globals.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:403-454`
pub fn CreateNewWP_FromObject(ctx: GameContext<'_>, wp: *mut wpobject_t) {
    unsafe {
        let w = ctx.world;
        if (*w).globals.gWPNum >= MAX_WPARRAY_SIZE {
            return;
        }

        let n = (*w).globals.gWPNum as usize;
        if (*w).globals.gWPArray.0[n].is_null() {
            (*w).globals.gWPArray.0[n] =
                B_Alloc(ctx, size_of::<wpobject_t>() as c_int) as *mut wpobject_t;
        }

        if (*w).globals.gWPArray.0[n].is_null() {
            G_Printf(ctx, c"^1ERROR: Could not allocated memory for waypoint\n".as_ptr());
        }

        let p = (*w).globals.gWPArray.0[n];
        (*p).flags = (*wp).flags;
        (*p).weight = (*wp).weight;
        (*p).associated_entity = (*wp).associated_entity;
        (*p).disttonext = (*wp).disttonext;
        (*p).forceJumpTo = (*wp).forceJumpTo;
        (*p).index = (*w).globals.gWPNum;
        (*p).inuse = 1;
        (*p).origin = (*wp).origin;
        (*p).neighbornum = (*wp).neighbornum;

        let mut i = (*wp).neighbornum;
        while i >= 0 {
            (*p).neighbors[i as usize].num = (*wp).neighbors[i as usize].num;
            (*p).neighbors[i as usize].forceJumpTo = (*wp).neighbors[i as usize].forceJumpTo;
            i -= 1;
        }

        if (*p).flags & WPFLAG_RED_FLAG != 0 {
            (*w).globals.flagRed = p;
            (*w).globals.oFlagRed = (*w).globals.flagRed;
        } else if (*p).flags & WPFLAG_BLUE_FLAG != 0 {
            (*w).globals.flagBlue = p;
            (*w).globals.oFlagBlue = (*w).globals.flagBlue;
        }

        (*w).globals.gWPNum += 1;
    }
}

/// Raven `RemoveWP`.
///
/// Pops the last waypoint. Faithfully reproduces Raven's `memset(p, 0,
/// sizeof(p))` — `sizeof` of the *pointer*, not the object, so only the first
/// `size_of::<*mut wpobject_t>()` bytes (`origin[0..1]`) are zeroed before
/// `inuse` is cleared; the slot memory is reused, never freed.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:456-482`
pub fn RemoveWP(ctx: GameContext<'_>) {
    unsafe {
        let w = ctx.world;
        if (*w).globals.gWPNum <= 0 {
            return;
        }

        (*w).globals.gWPNum -= 1;
        let n = (*w).globals.gWPNum as usize;

        let p = (*w).globals.gWPArray.0[n];
        if p.is_null() || (*p).inuse == 0 {
            return;
        }

        // `memset( gWPArray[gWPNum], 0, sizeof(gWPArray[gWPNum]) )` — pointer size.
        core::ptr::write_bytes(p as *mut u8, 0, size_of::<*mut wpobject_t>());
        (*p).inuse = 0;
    }
}

/// Raven `RemoveAllWP`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:484-489`
pub fn RemoveAllWP(ctx: GameContext<'_>) {
    unsafe {
        while (*ctx.world).globals.gWPNum != 0 {
            RemoveWP(ctx);
        }
    }
}

/// Raven `RemoveWP_InTrail`.
///
/// Removes the waypoint with index `afterindex` and shuffles the rest down one
/// slot. The pointer-sized `memset` idiom is Raven's (see `RemoveWP`).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:491-557`
pub fn RemoveWP_InTrail(ctx: GameContext<'_>, afterindex: c_int) {
    unsafe {
        let w = ctx.world;
        let mut foundindex: c_int = 0;
        let mut foundanindex = 0;
        let mut didchange = 0;
        let mut i: c_int = 0;

        if afterindex < 0 || afterindex >= (*w).globals.gWPNum {
            G_Printf(ctx, c"^3Waypoint number %i does not exist\n".as_ptr());
            return;
        }

        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 && (*p).index == afterindex {
                foundindex = i;
                foundanindex = 1;
                break;
            }
            i += 1;
        }

        if foundanindex == 0 {
            G_Printf(ctx, c"^3Waypoint index %i should exist, but does not (?)\n".as_ptr());
            return;
        }

        i = 0;
        while i <= (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).index == foundindex {
                core::ptr::write_bytes(p as *mut u8, 0, size_of::<*mut wpobject_t>());
                (*p).inuse = 0;
                didchange = 1;
            } else if !p.is_null() && didchange != 0 {
                TransferWPData(ctx, i, i - 1);
                core::ptr::write_bytes(p as *mut u8, 0, size_of::<*mut wpobject_t>());
                (*p).inuse = 0;
            }
            i += 1;
        }
        (*w).globals.gWPNum -= 1;
    }
}

/// Raven `CreateNewWP_InTrail`.
///
/// Inserts a new waypoint immediately *after* index `afterindex`, shifting the
/// tail up one slot. `origin` is read-only (fork-9: by-value).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:559-635`
pub fn CreateNewWP_InTrail(
    ctx: GameContext<'_>,
    origin: vec3_t,
    flags: c_int,
    afterindex: c_int,
) -> c_int {
    unsafe {
        let w = ctx.world;
        let mut foundindex: c_int = 0;
        let mut foundanindex = 0;
        let mut i: c_int = 0;

        if (*w).globals.gWPNum >= MAX_WPARRAY_SIZE {
            if (*w).cvars.g_RMG.integer == 0 {
                G_Printf(ctx, c"^3Warning: Waypoint limit hit (%i)\n".as_ptr());
            }
            return 0;
        }

        if afterindex < 0 || afterindex >= (*w).globals.gWPNum {
            G_Printf(ctx, c"^3Waypoint number %i does not exist\n".as_ptr());
            return 0;
        }

        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 && (*p).index == afterindex {
                foundindex = i;
                foundanindex = 1;
                break;
            }
            i += 1;
        }

        if foundanindex == 0 {
            G_Printf(ctx, c"^3Waypoint index %i should exist, but does not (?)\n".as_ptr());
            return 0;
        }

        i = (*w).globals.gWPNum;
        while i >= 0 {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 && (*p).index != foundindex {
                TransferWPData(ctx, i, i + 1);
            } else if !p.is_null() && (*p).inuse != 0 && (*p).index == foundindex {
                i += 1;

                if (*w).globals.gWPArray.0[i as usize].is_null() {
                    (*w).globals.gWPArray.0[i as usize] =
                        B_Alloc(ctx, size_of::<wpobject_t>() as c_int) as *mut wpobject_t;
                }

                let np = (*w).globals.gWPArray.0[i as usize];
                (*np).flags = flags;
                (*np).weight = 0.0;
                (*np).associated_entity = ENTITYNUM_NONE;
                (*np).disttonext = 0.0;
                (*np).forceJumpTo = 0;
                (*np).index = i;
                (*np).inuse = 1;
                (*np).origin = origin;
                (*w).globals.gWPNum += 1;
                break;
            }

            i -= 1;
        }

        1
    }
}

