/// Raven `TeleportToWP`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:716-758`
pub fn TeleportToWP(ctx: GameContext<'_>, pl: *mut gentity_t, afterindex: c_int) {
    unsafe {
        let w = ctx.world;
        if pl.is_null() || (*pl).client.is_null() {
            return;
        }

        let mut foundindex: c_int = 0;
        let mut foundanindex = 0;
        let mut i: c_int = 0;

        if afterindex < 0 || afterindex >= (*w).globals.gWPNum {
            G_Printf(ctx, c"^3Waypoint number %i does not exist\n".as_ptr());
            return;
        }

        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 && (*p).index == afterindex {
                foundindex = i;
                foundanindex = 1;
                break;
            }
            i += 1;
        }

        if foundanindex == 0 {
            G_Printf(ctx, c"^3Waypoint index %i should exist, but does not (?)\n".as_ptr());
            return;
        }

        let cl = (*pl).client as *mut gclient_t;
        (*cl).ps.origin = (*(*w).globals.gWPArray.0[foundindex as usize]).origin;
    }
}

/// Raven `WPFlagsModify`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:760-769`
pub fn WPFlagsModify(ctx: GameContext<'_>, wpnum: c_int, flags: c_int) {
    unsafe {
        let w = ctx.world;
        let p = if wpnum >= 0 && wpnum < (*w).globals.gWPNum {
            (*w).globals.gWPArray.0[wpnum as usize]
        } else {
            core::ptr::null_mut()
        };

        if wpnum < 0 || wpnum >= (*w).globals.gWPNum || p.is_null() || (*p).inuse == 0 {
            G_Printf(ctx, c"^3WPFlagsModify: Waypoint %i does not exist\n".as_ptr());
            return;
        }

        (*p).flags = flags;
    }
}

/// Raven `NotWithinRange` (file-static).
///
/// Pure integer range check — no globals, no traps.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:771-784`
pub fn NotWithinRange(base: c_int, extent: c_int) -> c_int {
    if extent > base && base + 5 >= extent {
        return 0;
    }
    if extent < base && base - 5 <= extent {
        return 0;
    }
    1
}

/// Raven `NodeHere`.
///
/// Whether a node already sits at (integer-truncated) `spot` X/Y with Z within
/// ±5. `spot` is read-only (fork-9: by-value).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:787-809`
pub fn NodeHere(ctx: GameContext<'_>, spot: vec3_t) -> c_int {
    unsafe {
        let w = ctx.world;
        let sx = spot[0] as c_int;
        let sy = spot[1] as c_int;
        let sz = spot[2] as c_int;
        let mut i: c_int = 0;

        while i < (*w).globals.nodenum {
            let o = (*w).globals.nodetable.0[i as usize].origin;
            let nx = o[0] as c_int;
            let ny = o[1] as c_int;
            let nz = o[2] as c_int;
            if nx == sx && ny == sy {
                if nz == sz || (nz < sz && nz + 5 > sz) || (nz > sz && nz - 5 < sz) {
                    return 1;
                }
            }
            i += 1;
        }

        0
    }
}

/// Raven `CanGetToVector`.
///
/// Single solid box-trace between two points; no file-scope state. `org1`/
/// `org2`/`mins`/`maxs` are read-only trace args (never written), so they
/// stay by-value `vec3_t` (fork-9: keep-by-value when never written).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:812-824`
pub fn CanGetToVector(
    ctx: GameContext<'_>,org1: vec3_t, org2: vec3_t, mins: vec3_t, maxs: vec3_t) -> c_int {
    // `ENTITYNUM_NONE` comes from `mp_qshared::shared::limits` (prelude glob).
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        trap::Trace(
            ctx.engine,
            GTraceArgs::new(&mut tr, &org1, &mins, &maxs, &org2, ENTITYNUM_NONE, MASK_SOLID),
        );

        if tr.fraction == 1.0 && tr.startsolid == 0 && tr.allsolid == 0 {
            return 1;
        }
    }
    0
}

/// Raven `CanGetToVectorTravel`.
///
/// Walks a box from `org1` toward `moveTo` in `stepSize` increments, allowing a
/// single 16-unit stair step, and reports whether any progress was made. All
/// four `vec3_t` args are read-only (fork-9: by-value). (The `#if 0` block at
/// `ai_wpnav.c:826-882` is dead source, dropped per §20.)
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:883-996`
pub fn CanGetToVectorTravel(
    ctx: GameContext<'_>,
    org1: vec3_t,
    moveTo: vec3_t,
    mins: vec3_t,
    maxs: vec3_t,
) -> c_int {
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        let mut step_size: f32 = 0.0;
        let mut did_move: c_int = 0;
        let trace_mask = MASK_PLAYERSOLID;
        let mut initial_done = false;

        let mut working_org: vec3_t = org1;
        let mut last_increment: vec3_t = org1;

        let mut step_to: vec3_t = moveTo;
        step_to[2] = working_org[2];

        let mut step_sub: vec3_t = [
            step_to[0] - working_org[0],
            step_to[1] - working_org[1],
            step_to[2] - working_org[2],
        ];
        step_size = VectorLength(step_sub); // length of the XY-levelled delta
        crate::q_math::VectorNormalize(&mut step_sub);

        while !initial_done || did_move != 0 {
            initial_done = true;
            did_move = 0;

            let step_goal: vec3_t = [
                working_org[0] + step_sub[0] * step_size,
                working_org[1] + step_sub[1] * step_size,
                working_org[2] + step_sub[2] * step_size,
            ];

            wp_trace(ctx, &mut tr, &working_org, &mins, &maxs, &step_goal, ENTITYNUM_NONE, trace_mask);

            if tr.startsolid == 0 && tr.allsolid == 0 && tr.fraction != 0.0 {
                let vec_sub: vec3_t = [
                    working_org[0] - tr.endpos[0],
                    working_org[1] - tr.endpos[1],
                    working_org[2] - tr.endpos[2],
                ];
                if VectorLength(vec_sub) > step_size / 2.0 {
                    working_org[0] = tr.endpos[0];
                    working_org[1] = tr.endpos[1];
                    did_move = 1;
                }
            }

            if did_move != 1 {
                // stair check
                let mut tr_from: vec3_t = tr.endpos;
                tr_from[2] += 16.0;

                let mut tr_dir: vec3_t = [
                    step_goal[0] - working_org[0],
                    step_goal[1] - working_org[1],
                    step_goal[2] - working_org[2],
                ];
                crate::q_math::VectorNormalize(&mut tr_dir);

                let mut tr_to: vec3_t = [
                    tr.endpos[0] + tr_dir[0] * 2.0,
                    tr.endpos[1] + tr_dir[1] * 2.0,
                    tr.endpos[2] + tr_dir[2] * 2.0,
                ];
                tr_to[2] += 16.0;

                let vec_measure: vec3_t = [
                    tr_from[0] - tr_to[0],
                    tr_from[1] - tr_to[1],
                    tr_from[2] - tr_to[2],
                ];

                if VectorLength(vec_measure) > 1.0 {
                    wp_trace(ctx, &mut tr, &tr_from, &mins, &maxs, &tr_to, ENTITYNUM_NONE, trace_mask);

                    if tr.startsolid == 0 && tr.allsolid == 0 && tr.fraction == 1.0 {
                        // clear trace here, probably up a step
                        let _tr_up: vec3_t = tr.endpos;
                        let mut tr_down: vec3_t = tr.endpos;
                        tr_down[2] -= 16.0;

                        wp_trace(ctx, &mut tr, &tr_from, &mins, &maxs, &tr_to, ENTITYNUM_NONE, trace_mask);

                        if tr.startsolid == 0 && tr.allsolid == 0 {
                            working_org = tr.endpos;
                            did_move = 1;
                        }
                    }
                }
            }

            let final_measure: vec3_t = [
                last_increment[0] - working_org[0],
                last_increment[1] - working_org[1],
                last_increment[2] - working_org[2],
            ];
            let measure_length = VectorLength(final_measure);

            if measure_length == 0.0 {
                break; // no progress
            }

            step_size -= measure_length;
            if step_size <= 0.0 {
                break;
            }

            last_increment = working_org;
        }

        did_move
    }
}

/// Raven `ConnectTrail`.
///
/// Branch-searches the node grid from `startindex` to `endindex`, then walks
/// the found chain back inserting waypoints. Falls back to a one-way flag pair
/// when unreachable. (The `g_RMG` short-circuit at the top means the inner
/// `g_RMG` branch-distance block is only reached when `g_RMG` is off; it is
/// transcribed faithfully regardless.)
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1000-1399`
pub fn ConnectTrail(
    ctx: GameContext<'_>,
    startindex: c_int,
    endindex: c_int,
    behindTheScenes: qboolean,
) -> c_int {
    // Try to drop one branch node offset by (dx,dy) from node `i`; returns true
    // when a node was appended (sets `cancontinue`). Mirrors the four repeated
    // X±/Y± blocks in the oracle.
    unsafe fn branch_dir(
        ctx: GameContext<'_>,
        i: c_int,
        dx: f32,
        dy: f32,
        base_height: f32,
        mins: vec3_t,
        maxs: vec3_t,
    ) -> bool {
        let w = ctx.world;
        let mut testspot = (*w).globals.nodetable.0[i as usize].origin;
        testspot[0] += dx;
        testspot[1] += dy;

        let mut starttrace = testspot;
        starttrace[2] -= 4096.0;

        let mut tr: trace_t = core::mem::zeroed();
        wp_trace(
            ctx,
            &mut tr,
            &testspot,
            core::ptr::null(),
            core::ptr::null(),
            &starttrace,
            ENTITYNUM_NONE,
            MASK_SOLID,
        );

        testspot[2] = tr.endpos[2] + base_height;

        let src = (*w).globals.nodetable.0[i as usize].origin;
        if NodeHere(ctx, testspot) == 0
            && tr.startsolid == 0
            && tr.allsolid == 0
            && CanGetToVector(ctx, src, testspot, mins, maxs) != 0
        {
            let nn = (*w).globals.nodenum as usize;
            (*w).globals.nodetable.0[nn].origin = testspot;
            (*w).globals.nodetable.0[nn].inuse = 1;
            (*w).globals.nodetable.0[nn].weight = (*w).globals.nodetable.0[i as usize].weight + 1.0;
            (*w).globals.nodetable.0[nn].neighbornum = i;
            if (*w).globals.nodetable.0[i as usize].origin[2] - (*w).globals.nodetable.0[nn].origin[2]
                > 50.0
            {
                // big drop — can't magically fly back up
                (*w).globals.nodetable.0[nn].flags = WPFLAG_ONEWAY_FWD;
            }
            (*w).globals.nodenum += 1;
            return true;
        }
        false
    }

    unsafe {
        let w = ctx.world;
        let mut foundit: c_int = 0;
        let mut cancontinue: c_int;
        let mut i: c_int;
        let mut failsafe: c_int;
        let mut successnodeindex: c_int = 0;
        let insertindex: c_int;
        let mut prenodestart: c_int;
        let mut extendednodes = [0u8; MAX_NODETABLE_SIZE as usize];
        let mut fvecmeas: f32;
        let baseheight: f32;
        let mut branch_distance: f32;
        let mut max_dist_factor: f32 = 256.0;
        let mins: vec3_t = [-15.0, -15.0, 0.0];
        let maxs: vec3_t = [15.0, 15.0, 0.0];

        if (*w).cvars.g_RMG.integer != 0 {
            // this might be temporary. Or not.
            let sp = (*w).globals.gWPArray.0[startindex as usize];
            let ep = (*w).globals.gWPArray.0[endindex as usize];
            if (*sp).flags & WPFLAG_NEVERONEWAY == 0 && (*ep).flags & WPFLAG_NEVERONEWAY == 0 {
                (*sp).flags |= WPFLAG_ONEWAY_FWD;
                (*ep).flags |= WPFLAG_ONEWAY_BACK;
            }
            return 0;
        }

        if (*w).cvars.g_RMG.integer == 0 {
            branch_distance = TABLE_BRANCH_DISTANCE;
        } else {
            branch_distance = 512.0; // be less precise on broad terrain
        }

        if (*w).cvars.g_RMG.integer != 0 {
            max_dist_factor = 700.0;
        }

        (*w).globals.nodenum = 0;
        foundit = 0;
        i = 0;
        successnodeindex = 0;

        // clear the node table before using it
        while i < MAX_NODETABLE_SIZE {
            let nt = &mut (*w).globals.nodetable.0[i as usize];
            nt.flags = 0;
            nt.inuse = 0;
            nt.neighbornum = 0;
            nt.origin = [0.0, 0.0, 0.0];
            nt.weight = 0.0;
            extendednodes[i as usize] = 0;
            i += 1;
        }

        i = 0;

        if behindTheScenes == 0 {
            G_Printf(ctx, c"^3Point %i is not connected to %i - Repairing...\n".as_ptr());
        }

        let startplace = (*(*w).globals.gWPArray.0[startindex as usize]).origin;
        let mut starttrace = startplace;
        starttrace[2] -= 4096.0;

        let mut tr: trace_t = core::mem::zeroed();
        wp_trace(
            ctx,
            &mut tr,
            &startplace,
            core::ptr::null(),
            core::ptr::null(),
            &starttrace,
            ENTITYNUM_NONE,
            MASK_SOLID,
        );

        baseheight = startplace[2] - tr.endpos[2];
        cancontinue = 1;

        {
            let nn = (*w).globals.nodenum as usize;
            (*w).globals.nodetable.0[nn].origin = startplace;
            (*w).globals.nodetable.0[nn].weight = 1.0;
            (*w).globals.nodetable.0[nn].inuse = 1;
            (*w).globals.nodenum += 1;
        }

        while (*w).globals.nodenum < MAX_NODETABLE_SIZE && foundit == 0 && cancontinue != 0 {
            if (*w).cvars.g_RMG.integer != 0 {
                // adjust branch distance by distance from start/end (RMG only)
                let last = ((*w).globals.nodenum - 1) as usize;
                let so = (*(*w).globals.gWPArray.0[startindex as usize]).origin;
                let eo = (*(*w).globals.gWPArray.0[endindex as usize]).origin;
                let no = (*w).globals.nodetable.0[last].origin;
                let start_distf = VectorLength([no[0] - so[0], no[1] - so[1], no[2] - so[2]]);
                let end_distf = VectorLength([no[0] - eo[0], no[1] - eo[1], no[2] - eo[2]]);
                if start_distf < 64.0 || end_distf < 64.0 {
                    branch_distance = 64.0;
                } else if start_distf < 128.0 || end_distf < 128.0 {
                    branch_distance = 128.0;
                } else if start_distf < 256.0 || end_distf < 256.0 {
                    branch_distance = 256.0;
                } else if start_distf < 512.0 || end_distf < 512.0 {
                    branch_distance = 512.0;
                } else {
                    branch_distance = 800.0;
                }
            }

            cancontinue = 0;
            i = 0;
            prenodestart = (*w).globals.nodenum;

            while i < prenodestart {
                if extendednodes[i as usize] != 1 {
                    let eo = (*(*w).globals.gWPArray.0[endindex as usize]).origin;
                    let no = (*w).globals.nodetable.0[i as usize].origin;
                    fvecmeas = VectorLength([eo[0] - no[0], eo[1] - no[1], eo[2] - no[2]]);

                    if fvecmeas < 128.0 && CanGetToVector(ctx, eo, no, mins, maxs) != 0 {
                        foundit = 1;
                        successnodeindex = i;
                        break;
                    }

                    if branch_dir(ctx, i, branch_distance, 0.0, baseheight, mins, maxs) {
                        cancontinue = 1;
                    }
                    if (*w).globals.nodenum >= MAX_NODETABLE_SIZE {
                        break;
                    }

                    if branch_dir(ctx, i, -branch_distance, 0.0, baseheight, mins, maxs) {
                        cancontinue = 1;
                    }
                    if (*w).globals.nodenum >= MAX_NODETABLE_SIZE {
                        break;
                    }

                    if branch_dir(ctx, i, 0.0, branch_distance, baseheight, mins, maxs) {
                        cancontinue = 1;
                    }
                    if (*w).globals.nodenum >= MAX_NODETABLE_SIZE {
                        break;
                    }

                    if branch_dir(ctx, i, 0.0, -branch_distance, baseheight, mins, maxs) {
                        cancontinue = 1;
                    }
                    if (*w).globals.nodenum >= MAX_NODETABLE_SIZE {
                        break;
                    }

                    extendednodes[i as usize] = 1;
                }

                i += 1;
            }
        }

        if foundit == 0 {
            // non-debug build: only print when not auto-pathing
            if behindTheScenes == 0 {
                G_Printf(
                    ctx,
                    c"^1Could not link %i to %i, unreachable by node branching.\n".as_ptr(),
                );
            }
            (*(*w).globals.gWPArray.0[startindex as usize]).flags |= WPFLAG_ONEWAY_FWD;
            (*(*w).globals.gWPArray.0[endindex as usize]).flags |= WPFLAG_ONEWAY_BACK;
            if behindTheScenes == 0 {
                G_Printf(
                    ctx,
                    c"^3Since points cannot be connected, point %i has been flagged as only-forward and point %i has been flagged as only-backward.\n".as_ptr(),
                );
            }

            if behindTheScenes == 0 {
                // just use what we have if auto-pathing the level
                return 0;
            } else {
                let mut n_count: c_int = 0;
                let mut ideal_node: c_int = -1;
                let mut best_dist: f32 = 0.0;
                let mut test_dist: f32;

                if (*w).globals.nodenum <= 10 {
                    return 0; // not enough to bother
                }

                // find whichever node is closest to the desired end
                while n_count < (*w).globals.nodenum {
                    let no = (*w).globals.nodetable.0[n_count as usize].origin;
                    let eo = (*(*w).globals.gWPArray.0[endindex as usize]).origin;
                    test_dist = VectorLength([no[0] - eo[0], no[1] - eo[1], no[2] - eo[2]]);
                    if ideal_node == -1 {
                        ideal_node = n_count;
                        best_dist = test_dist;
                        n_count += 1;
                        continue;
                    }

                    if test_dist < best_dist {
                        ideal_node = n_count;
                        best_dist = test_dist;
                    }

                    n_count += 1;
                }

                if ideal_node == -1 {
                    return 0;
                }

                successnodeindex = ideal_node;
            }
        }

        i = successnodeindex;
        insertindex = startindex;
        failsafe = 0;
        let mut validspotpos = (*(*w).globals.gWPArray.0[startindex as usize]).origin;

        while failsafe < MAX_NODETABLE_SIZE && i < MAX_NODETABLE_SIZE && i >= 0 {
            let no = (*w).globals.nodetable.0[i as usize].origin;
            let a = [validspotpos[0] - no[0], validspotpos[1] - no[1], validspotpos[2] - no[2]];
            let neigh = (*w).globals.nodetable.0[i as usize].neighbornum;
            let eo = (*(*w).globals.gWPArray.0[endindex as usize]).origin;

            if (*w).globals.nodetable.0[neigh as usize].inuse == 0
                || CanGetToVectorTravel(ctx, validspotpos, no, mins, maxs) == 0
                || VectorLength(a) > max_dist_factor
                || (CanGetToVectorTravel(ctx, validspotpos, eo, mins, maxs) == 0
                    && CanGetToVectorTravel(ctx, no, eo, mins, maxs) != 0)
            {
                (*w).globals.nodetable.0[i as usize].flags |= WPFLAG_CALCULATED;
                let nf = (*w).globals.nodetable.0[i as usize].flags;
                if CreateNewWP_InTrail(ctx, no, nf, insertindex) == 0 {
                    if behindTheScenes == 0 {
                        G_Printf(
                            ctx,
                            c"^1Could not link %i to %i, waypoint limit hit.\n".as_ptr(),
                        );
                    }
                    return 0;
                }

                validspotpos = no;
            }

            if i == 0 {
                break;
            }

            i = (*w).globals.nodetable.0[i as usize].neighbornum;
            failsafe += 1;
        }

        if behindTheScenes == 0 {
            G_Printf(ctx, c"^3Finished connecting %i to %i.\n".as_ptr());
        }

        1
    }
}

/// Raven `OpposingEnds`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1402-1416`
pub fn OpposingEnds(ctx: GameContext<'_>, start: c_int, end: c_int) -> c_int {
    unsafe {
        let w = ctx.world;
        let sp = (*w).globals.gWPArray.0[start as usize];
        let ep = (*w).globals.gWPArray.0[end as usize];
        if sp.is_null() || (*sp).inuse == 0 || ep.is_null() || (*ep).inuse == 0 {
            return 0;
        }

        if (*sp).flags & WPFLAG_ONEWAY_FWD != 0 && (*ep).flags & WPFLAG_ONEWAY_BACK != 0 {
            return 1;
        }

        0
    }
}

/// Raven `DoorBlockingSection`.
///
/// If a `func_` brush blocks both directions of the segment, treat it as an
/// (openable) door and let the two endpoints stay linked.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1418-1463`
pub fn DoorBlockingSection(ctx: GameContext<'_>, start: c_int, end: c_int) -> c_int {
    unsafe {
        let w = ctx.world;
        let sp = (*w).globals.gWPArray.0[start as usize];
        let ep = (*w).globals.gWPArray.0[end as usize];
        if sp.is_null() || (*sp).inuse == 0 || ep.is_null() || (*ep).inuse == 0 {
            return 0;
        }

        let mut tr: trace_t = core::mem::zeroed();
        let s_org = (*sp).origin;
        let e_org = (*ep).origin;
        wp_trace(
            ctx, &mut tr, &s_org, core::ptr::null(), core::ptr::null(), &e_org,
            ENTITYNUM_NONE, MASK_SOLID,
        );

        if tr.fraction == 1.0 {
            return 0;
        }

        let cn = (*w).entities[tr.entityNum as usize].classname;
        // Raven derefs `testdoor->classname` unconditionally; a slot with a
        // null classname would crash there — the one defined behavior here is
        // "no `func_` match" (returns 0). (§19)
        if cn.is_null() {
            return 0;
        }
        if !c_str_contains(cn, b"func_") {
            return 0;
        }

        let start_trace_index = tr.entityNum;

        wp_trace(
            ctx, &mut tr, &e_org, core::ptr::null(), core::ptr::null(), &s_org,
            ENTITYNUM_NONE, MASK_SOLID,
        );

        if tr.fraction == 1.0 {
            return 0;
        }

        if start_trace_index == tr.entityNum {
            return 1;
        }

        0
    }
}

/// `strstr`-style substring test on a NUL-terminated C string.
unsafe fn c_str_contains(s: *const c_char, needle: &[u8]) -> bool {
    if s.is_null() {
        return false;
    }
    let bytes = core::ffi::CStr::from_ptr(s).to_bytes();
    bytes.windows(needle.len()).any(|w| w == needle)
}

/// Raven `RepairPaths`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1466-1523`
pub fn RepairPaths(ctx: GameContext<'_>, behindTheScenes: qboolean) -> c_int {
    unsafe {
        let w = ctx.world;

        if (*w).globals.gWPNum == 0 {
            return 0;
        }

        let mut max_dist_factor: f32 = 400.0;
        if (*w).cvars.g_RMG.integer != 0 {
            max_dist_factor = 800.0; // higher tolerance here.
        }

        let mut i: c_int = 0;

        // PORT-NOTE(cvar-placement): `bot_wp_distconnect`/`bot_wp_visconnect`
        // are `ai_wpnav.c` file-scope `vmCvar_t` handles with no home in
        // `GameCvars` yet (missing_symbols).
        trap::Cvar_Update(
            ctx.engine,
            GCvarUpdateArgs::new(&mut (*w).cvars.bot_wp_distconnect as *mut vmCvar_t),
        );
        trap::Cvar_Update(
            ctx.engine,
            GCvarUpdateArgs::new(&mut (*w).cvars.bot_wp_visconnect as *mut vmCvar_t),
        );

        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            let pn = (*w).globals.gWPArray.0[(i + 1) as usize];

            if !p.is_null() && (*p).inuse != 0 && !pn.is_null() && (*pn).inuse != 0 {
                let a = [
                    (*p).origin[0] - (*pn).origin[0],
                    (*p).origin[1] - (*pn).origin[1],
                    (*p).origin[2] - (*pn).origin[2],
                ];

                if (*pn).flags & WPFLAG_NOVIS == 0
                    && (*pn).flags & WPFLAG_JUMP == 0
                    && (*p).flags & WPFLAG_CALCULATED == 0
                    && OpposingEnds(ctx, i, i + 1) == 0
                    && (((*w).cvars.bot_wp_distconnect.value != 0.0 && VectorLength(a) > max_dist_factor)
                        || (OrgVisible(ctx, (*p).origin, (*pn).origin, ENTITYNUM_NONE) == 0
                            && (*w).cvars.bot_wp_visconnect.value != 0.0))
                    && DoorBlockingSection(ctx, i, i + 1) == 0
                {
                    let _ct_ret = ConnectTrail(ctx, i, i + 1, behindTheScenes);

                    if (*w).globals.gWPNum >= MAX_WPARRAY_SIZE {
                        // Bad!
                        (*w).globals.gWPNum = MAX_WPARRAY_SIZE;
                        break;
                    }

                    // if (!ctRet) { return 0; } // we still want to write it..
                }
            }

            i += 1;
        }

        1
    }
}

/// Raven `OrgVisibleCurve`.
///
/// Double solid box-trace along a levelled path segment; no file-scope state.
/// All `vec3_t` args are read-only trace args (`org1`/`org2`/`mins`/`maxs`),
/// so they stay by-value (fork-9: keep-by-value when never written).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1526-1547`
pub fn OrgVisibleCurve(
    ctx: GameContext<'_>,org1: vec3_t, mins: vec3_t, maxs: vec3_t, org2: vec3_t, ignore: c_int) -> c_int {
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        let mut evenorg1: vec3_t = org1;
        evenorg1[2] = org2[2];

        trap::Trace(
            ctx.engine,
            GTraceArgs::new(&mut tr, &evenorg1, &mins, &maxs, &org2, ignore, MASK_SOLID),
        );

        if tr.fraction == 1.0 && tr.startsolid == 0 && tr.allsolid == 0 {
            trap::Trace(
                ctx.engine,
                GTraceArgs::new(&mut tr, &evenorg1, &mins, &maxs, &org1, ignore, MASK_SOLID),
            );

            if tr.fraction == 1.0 && tr.startsolid == 0 && tr.allsolid == 0 {
                return 1;
            }
        }
    }
    0
}

/// Raven `CanForceJumpTo`.
///
/// Returns a nonzero force-jump "level" (1/2/3) when `testingindex` is a
/// reachable force-jump-up target from `baseindex`, else 0.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1549-1621`
pub fn CanForceJumpTo(
    ctx: GameContext<'_>,
    baseindex: c_int,
    testingindex: c_int,
    distance: f32,
) -> c_int {
    unsafe {
        let w = ctx.world;
        let heightdif: f32;
        let mins: vec3_t = [-15.0, -15.0, -15.0];
        let maxs: vec3_t = [15.0, 15.0, 15.0];
        let wp_base = (*w).globals.gWPArray.0[baseindex as usize];
        let wp_test = (*w).globals.gWPArray.0[testingindex as usize];

        if wp_base.is_null() || (*wp_base).inuse == 0 || wp_test.is_null() || (*wp_test).inuse == 0 {
            return 0;
        }

        if distance > 400.0 {
            return 0;
        }

        let mut xy_base = (*wp_base).origin;
        let xy_test = (*wp_test).origin;
        xy_base[2] = xy_test[2];

        let v = [xy_base[0] - xy_test[0], xy_base[1] - xy_test[1], xy_base[2] - xy_test[2]];
        if VectorLength(v) > MAX_NEIGHBOR_LINK_DISTANCE {
            return 0;
        }

        if ((*wp_base).origin[2] as c_int) < ((*wp_test).origin[2] as c_int) {
            heightdif = (*wp_test).origin[2] - (*wp_base).origin[2];
        } else {
            return 0; // err..
        }

        if heightdif < 128.0 {
            return 0; // don't bother
        }

        if heightdif > 512.0 {
            return 0; // too high
        }

        if OrgVisibleCurve(ctx, (*wp_base).origin, mins, maxs, (*wp_test).origin, ENTITYNUM_NONE) == 0
        {
            return 0;
        }

        if heightdif > 400.0 {
            3
        } else if heightdif > 256.0 {
            2
        } else {
            1
        }
    }
}

/// Raven `CalculatePaths`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1623-1713`
pub fn CalculatePaths(ctx: GameContext<'_>) {
    unsafe {
        let w = ctx.world;

        if (*w).globals.gWPNum == 0 {
            return;
        }

        let mut max_neighbor_dist: f32 = MAX_NEIGHBOR_LINK_DISTANCE;
        if (*w).cvars.g_RMG.integer != 0 {
            max_neighbor_dist = DEFAULT_GRID_SPACING + (DEFAULT_GRID_SPACING * 0.5);
        }

        let mins: vec3_t = [-15.0, -15.0, -15.0];
        let maxs: vec3_t = [15.0, 15.0, 15.0];

        // clear out all the neighbor data before we recalculate
        let mut i: c_int = 0;
        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 && (*p).neighbornum != 0 {
                while (*p).neighbornum >= 0 {
                    (*p).neighbors[(*p).neighbornum as usize].num = 0;
                    (*p).neighbors[(*p).neighbornum as usize].forceJumpTo = 0;
                    (*p).neighbornum -= 1;
                }
                (*p).neighbornum = 0;
            }
            i += 1;
        }

        i = 0;
        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 {
                let mut c: c_int = 0;
                while c < (*w).globals.gWPNum {
                    let cp = (*w).globals.gWPArray.0[c as usize];
                    if !cp.is_null() && (*cp).inuse != 0 && i != c && NotWithinRange(i, c) != 0 {
                        let a = [
                            (*p).origin[0] - (*cp).origin[0],
                            (*p).origin[1] - (*cp).origin[1],
                            (*p).origin[2] - (*cp).origin[2],
                        ];

                        let n_l_dist = VectorLength(a);
                        let force_jumpable = CanForceJumpTo(ctx, i, c, n_l_dist);

                        if (n_l_dist < max_neighbor_dist || force_jumpable != 0)
                            && ((*p).origin[2] as c_int == (*cp).origin[2] as c_int || force_jumpable != 0)
                            && (OrgVisibleBox(ctx, (*p).origin, mins, maxs, (*cp).origin, ENTITYNUM_NONE) != 0
                                || force_jumpable != 0)
                        {
                            (*p).neighbors[(*p).neighbornum as usize].num = c;
                            if force_jumpable != 0
                                && ((*p).origin[2] as c_int != (*cp).origin[2] as c_int
                                    || n_l_dist < max_neighbor_dist)
                            {
                                (*p).neighbors[(*p).neighbornum as usize].forceJumpTo = 999; // forceJumpable; //FJSR
                            } else {
                                (*p).neighbors[(*p).neighbornum as usize].forceJumpTo = 0;
                            }
                            (*p).neighbornum += 1;
                        }

                        if (*p).neighbornum >= MAX_NEIGHBOR_SIZE as c_int {
                            break;
                        }
                    }
                    c += 1;
                }
            }
            i += 1;
        }
    }
}

/// Raven `GetObjectThatTargets`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1715-1732`
pub fn GetObjectThatTargets(ctx: GameContext<'_>, ent: *mut gentity_t) -> *mut gentity_t {
    unsafe {
        if (*ent).targetname.is_null() {
            return core::ptr::null_mut();
        }

        // `FOFS(target)` — byte offset of `gentity_t::target` — is the field
        // this scan matches against.
        let fieldofs = core::mem::offset_of!(gentity_t, target) as c_int;
        let next = G_Find(ctx, core::ptr::null_mut(), fieldofs, (*ent).targetname);

        if !next.is_null() {
            return next;
        }

        core::ptr::null_mut()
    }
}

/// Raven `CalculateSiegeGoals`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1734-1794`
pub fn CalculateSiegeGoals(ctx: GameContext<'_>) {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;

        while i < (*w).level.num_entities {
            let ent: *mut gentity_t = &mut (*w).entities[i as usize];

            let mut tent: *mut gentity_t = core::ptr::null_mut();

            if !ent.is_null() && !(*ent).classname.is_null() && c_str_eq((*ent).classname, b"info_siege_objective") {
                tent = ent;
                let mut t2ent = GetObjectThatTargets(ctx, tent);
                let mut looptracker: c_int = 0;

                while !t2ent.is_null() && looptracker < 2048 {
                    // looptracker keeps us from getting stuck in case something is set up weird on this map
                    tent = t2ent;
                    t2ent = GetObjectThatTargets(ctx, tent);
                    looptracker += 1;
                }

                if looptracker >= 2048 {
                    // something unpleasent has happened
                    tent = core::ptr::null_mut();
                    break;
                }
            }

            if !tent.is_null() && !ent.is_null() && tent != ent {
                // tent should now be the object attached to the mission objective
                let dif = [
                    ((*tent).r.absmax[0] + (*tent).r.absmin[0]) / 2.0,
                    ((*tent).r.absmax[1] + (*tent).r.absmin[1]) / 2.0,
                    ((*tent).r.absmax[2] + (*tent).r.absmin[2]) / 2.0,
                ];

                let wpindex = GetNearestVisibleWP(ctx, dif, (*tent).s.number);

                if wpindex != -1 {
                    let p = (*w).globals.gWPArray.0[wpindex as usize];
                    if !p.is_null() && (*p).inuse != 0 {
                        // found the waypoint nearest the center of this objective-related object
                        if (*ent).side == SIEGETEAM_TEAM1 {
                            (*p).flags |= WPFLAG_SIEGE_IMPERIALOBJ;
                        } else {
                            (*p).flags |= WPFLAG_SIEGE_REBELOBJ;
                        }

                        (*p).associated_entity = (*tent).s.number;
                    }
                }
            }

            i += 1;
        }
    }
}

/// Raven `GetNearestVisibleWPToItem`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1817-1856`
pub fn GetNearestVisibleWPToItem(ctx: GameContext<'_>, org: vec3_t, ignore: c_int) -> c_int {
    unsafe {
        let w = ctx.world;

        let mut bestdist: f32 = 64.0; // has to be less than 64 units to the item or it isn't safe enough
        let mut bestindex: c_int = -1;

        let mins: vec3_t = [-15.0, -15.0, 0.0];
        let maxs: vec3_t = [15.0, 15.0, 0.0];

        let mut i: c_int = 0;
        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null()
                && (*p).inuse != 0
                && (*p).origin[2] - 15.0 < org[2]
                && (*p).origin[2] + 15.0 > org[2]
            {
                let a = [org[0] - (*p).origin[0], org[1] - (*p).origin[1], org[2] - (*p).origin[2]];
                let fl_len = VectorLength(a);

                if fl_len < bestdist {
                    let in_pvs = trap::InPVS(
                        ctx.engine,
                        GInPvsArgs::new(&org as *const vec3_t, &(*p).origin as *const vec3_t),
                    );
                    if in_pvs != 0 && OrgVisibleBox(ctx, org, mins, maxs, (*p).origin, ignore) != 0 {
                        bestdist = fl_len;
                        bestindex = i;
                    }
                }
            }

            i += 1;
        }

        bestindex
    }
}

/// Raven `CalculateWeightGoals`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1858-1951`
pub fn CalculateWeightGoals(ctx: GameContext<'_>) {
    // set waypoint weights depending on weapon and item placement
    unsafe {
        let w = ctx.world;

        // PORT-NOTE(cvar-placement): `bot_wp_clearweight` has no home in
        // `GameCvars` yet (missing_symbols).
        trap::Cvar_Update(
            ctx.engine,
            GCvarUpdateArgs::new(&mut (*w).cvars.bot_wp_clearweight as *mut vmCvar_t),
        );

        let mut i: c_int = 0;

        if (*w).cvars.bot_wp_clearweight.integer != 0 {
            // if set then flush out all weight/goal values before calculating them again
            while i < (*w).globals.gWPNum {
                let p = (*w).globals.gWPArray.0[i as usize];
                if !p.is_null() && (*p).inuse != 0 {
                    (*p).weight = 0.0;

                    if (*p).flags & WPFLAG_GOALPOINT != 0 {
                        (*p).flags -= WPFLAG_GOALPOINT;
                    }
                }

                i += 1;
            }
        }

        i = 0;

        while i < (*w).level.num_entities {
            let ent: *mut gentity_t = &mut (*w).entities[i as usize];

            let mut weight: f32 = 0.0;

            if !ent.is_null() && !(*ent).classname.is_null() {
                if c_str_eq((*ent).classname, b"item_seeker") {
                    weight = 2.0;
                } else if c_str_eq((*ent).classname, b"item_shield") {
                    weight = 2.0;
                } else if c_str_eq((*ent).classname, b"item_medpac") {
                    weight = 2.0;
                } else if c_str_eq((*ent).classname, b"item_sentry_gun") {
                    weight = 2.0;
                } else if c_str_eq((*ent).classname, b"item_force_enlighten_dark") {
                    weight = 5.0;
                } else if c_str_eq((*ent).classname, b"item_force_enlighten_light") {
                    weight = 5.0;
                } else if c_str_eq((*ent).classname, b"item_force_boon") {
                    weight = 5.0;
                } else if c_str_eq((*ent).classname, b"item_ysalimari") {
                    weight = 2.0;
                } else if c_str_contains((*ent).classname, b"weapon_") && !(*ent).item.is_null() {
                    // PORT-NOTE(missing-global): `botGlobalNavWeaponWeights`
                    // (`ai_wpnav.c:1796`) has no ported home yet
                    // (missing_symbols).
                    weight = botGlobalNavWeaponWeights[(*(*ent).item).giTag as usize];
                } else if !(*ent).item.is_null() && (*(*ent).item).giType == IT_AMMO {
                    weight = 3.0;
                }
            }

            if !ent.is_null() && weight != 0.0 {
                let wpindex = GetNearestVisibleWPToItem(ctx, (*ent).s.pos.trBase, (*ent).s.number);

                if wpindex != -1 {
                    let p = (*w).globals.gWPArray.0[wpindex as usize];
                    if !p.is_null() && (*p).inuse != 0 {
                        // found the waypoint nearest the center of this object
                        (*p).weight = weight;
                        (*p).flags |= WPFLAG_GOALPOINT;
                        (*p).associated_entity = (*ent).s.number;
                    }
                }
            }

            i += 1;
        }
    }
}

/// Raven `CalculateJumpRoutes`.
///
/// Marks jump waypoints that need force-jumping (999 = "FJSR" sentinel) by the
/// height drop to their trail neighbours.
///
/// The oracle reads `gWPArray[i-1]`/`gWPArray[i+1]` unguarded; at `i==0` that
/// is an out-of-bounds `gWPArray[-1]`, and `i+1` can reach one past the array —
/// the one defined behavior here treats those as null (skip the branch). (§19)
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:1953-2005`
pub fn CalculateJumpRoutes(ctx: GameContext<'_>) {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;
        let mut nheightdif: f32;
        let mut pheightdif: f32;

        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 {
                if (*p).flags & WPFLAG_JUMP != 0 {
                    nheightdif = 0.0;
                    pheightdif = 0.0;
                    (*p).forceJumpTo = 0;

                    let prev = if i >= 1 {
                        (*w).globals.gWPArray.0[(i - 1) as usize]
                    } else {
                        core::ptr::null_mut()
                    };
                    if !prev.is_null()
                        && (*prev).inuse != 0
                        && (*prev).origin[2] + 16.0 < (*p).origin[2]
                    {
                        nheightdif = (*p).origin[2] - (*prev).origin[2];
                    }

                    let next = if i + 1 < MAX_WPARRAY_SIZE {
                        (*w).globals.gWPArray.0[(i + 1) as usize]
                    } else {
                        core::ptr::null_mut()
                    };
                    if !next.is_null()
                        && (*next).inuse != 0
                        && (*next).origin[2] + 16.0 < (*p).origin[2]
                    {
                        pheightdif = (*p).origin[2] - (*next).origin[2];
                    }

                    if nheightdif > pheightdif {
                        pheightdif = nheightdif;
                    }

                    if pheightdif != 0.0 {
                        // FJSR: all three force levels collapse to the 999 sentinel
                        if pheightdif > 500.0 {
                            (*p).forceJumpTo = 999;
                        } else if pheightdif > 256.0 {
                            (*p).forceJumpTo = 999;
                        } else if pheightdif > 128.0 {
                            (*p).forceJumpTo = 999;
                        }
                    }
                }
            }

            i += 1;
        }
    }
}

/// Raven `LoadPathData`.
///
/// Hand-rolled route-file parser (`ai_wpnav.c:2007-2250`), transcribed as
/// direct byte-pointer indexing over the `B_TempAlloc`'d scratch buffers to
/// stay 1:1 with the oracle's char-array walk.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2007-2250`
pub fn LoadPathData(ctx: GameContext<'_>, filename: *const c_char) -> c_int {
    unsafe {
        let w = ctx.world;
        let mut i: isize = 0;
        let mut i_cv: isize;

        // Raven `B_TempAlloc`s `routePath` (1024 bytes), `Com_sprintf`s the
        // path into it, opens the file, then `B_TempFree`s it — we build the
        // path as an owned `String` directly but keep the alloc/free pair for
        // bump-allocator stack parity.
        let _route_path = B_TempAlloc(ctx, 1024);
        let filename_s = cstr_to_str(filename);
        let route_path_s = format!("botroutes/{}.wnt", filename_s);

        let mut f: fileHandle_t = 0;
        let len = trap::FS_FOpenFile(
            ctx.engine,
            GFsFopenFileArgs::new(CString::new(route_path_s).unwrap(), &mut f, FS_READ),
        );

        B_TempFree(ctx, 1024); // routePath

        if f == 0 {
            let s = format!("^3Bot route data not found for {}\n", filename_s);
            G_Printf(ctx, cstr(&s).as_ptr());
            return 2;
        }

        if len >= 524288 {
            let s = "^1Route file exceeds maximum length\n";
            G_Printf(ctx, cstr(s).as_ptr());
            return 0;
        }

        let file_string = B_TempAlloc(ctx, 524288) as *mut c_char;
        let current_var = B_TempAlloc(ctx, 2048) as *mut c_char;

        trap::FS_Read(
            ctx.engine,
            GFsReadArgs::new(file_string as *mut u8, len, f),
        );

        if *file_string.offset(i) == b'l' as c_char {
            // contains a "levelflags" entry..
            let mut read_lflags: [c_char; 64] = [0; 64];
            i_cv = 0;

            while *file_string.offset(i) != b' ' as c_char {
                i += 1;
            }
            i += 1;
            while *file_string.offset(i) != b'\n' as c_char {
                read_lflags[i_cv as usize] = *file_string.offset(i);
                i_cv += 1;
                i += 1;
            }
            read_lflags[i_cv as usize] = 0;
            i += 1;

            (*w).globals.gLevelFlags = crate::bg_lib::atoi(read_lflags.as_ptr());
        } else {
            (*w).globals.gLevelFlags = 0;
        }

        while i < len as isize {
            i_cv = 0;

            let mut thiswp: wpobject_t = core::mem::zeroed();
            thiswp.associated_entity = ENTITYNUM_NONE;

            let mut nei_num: c_int = 0;
            while (nei_num as usize) < MAX_NEIGHBOR_SIZE {
                thiswp.neighbors[nei_num as usize].num = 0;
                thiswp.neighbors[nei_num as usize].forceJumpTo = 0;
                nei_num += 1;
            }

            while *file_string.offset(i) != b' ' as c_char {
                *current_var.offset(i_cv) = *file_string.offset(i);
                i_cv += 1;
                i += 1;
            }
            *current_var.offset(i_cv) = 0;
            thiswp.index = crate::bg_lib::atoi(current_var);

            i_cv = 0;
            i += 1;

            while *file_string.offset(i) != b' ' as c_char {
                *current_var.offset(i_cv) = *file_string.offset(i);
                i_cv += 1;
                i += 1;
            }
            *current_var.offset(i_cv) = 0;
            thiswp.flags = crate::bg_lib::atoi(current_var);

            i_cv = 0;
            i += 1;

            while *file_string.offset(i) != b' ' as c_char {
                *current_var.offset(i_cv) = *file_string.offset(i);
                i_cv += 1;
                i += 1;
            }
            *current_var.offset(i_cv) = 0;
            thiswp.weight = atof(current_var) as f32;

            i_cv = 0;
            i += 1;
            i += 1;

            while *file_string.offset(i) != b' ' as c_char {
                *current_var.offset(i_cv) = *file_string.offset(i);
                i_cv += 1;
                i += 1;
            }
            *current_var.offset(i_cv) = 0;
            thiswp.origin[0] = atof(current_var) as f32;

            i_cv = 0;
            i += 1;

            while *file_string.offset(i) != b' ' as c_char {
                *current_var.offset(i_cv) = *file_string.offset(i);
                i_cv += 1;
                i += 1;
            }
            *current_var.offset(i_cv) = 0;
            thiswp.origin[1] = atof(current_var) as f32;

            i_cv = 0;
            i += 1;

            while *file_string.offset(i) != b')' as c_char {
                *current_var.offset(i_cv) = *file_string.offset(i);
                i_cv += 1;
                i += 1;
            }
            *current_var.offset(i_cv) = 0;
            thiswp.origin[2] = atof(current_var) as f32;

            i += 4;

            while *file_string.offset(i) != b'}' as c_char {
                i_cv = 0;
                while *file_string.offset(i) != b' ' as c_char && *file_string.offset(i) != b'-' as c_char {
                    *current_var.offset(i_cv) = *file_string.offset(i);
                    i_cv += 1;
                    i += 1;
                }
                *current_var.offset(i_cv) = 0;

                thiswp.neighbors[thiswp.neighbornum as usize].num = crate::bg_lib::atoi(current_var);

                if *file_string.offset(i) == b'-' as c_char {
                    i_cv = 0;
                    i += 1;

                    while *file_string.offset(i) != b' ' as c_char {
                        *current_var.offset(i_cv) = *file_string.offset(i);
                        i_cv += 1;
                        i += 1;
                    }
                    *current_var.offset(i_cv) = 0;

                    thiswp.neighbors[thiswp.neighbornum as usize].forceJumpTo = 999; // atoi(currentVar); //FJSR
                } else {
                    thiswp.neighbors[thiswp.neighbornum as usize].forceJumpTo = 0;
                }

                thiswp.neighbornum += 1;

                i += 1;
            }

            i_cv = 0;
            i += 1;
            i += 1;

            while *file_string.offset(i) != b'\n' as c_char {
                *current_var.offset(i_cv) = *file_string.offset(i);
                i_cv += 1;
                i += 1;
            }
            *current_var.offset(i_cv) = 0;

            thiswp.disttonext = atof(current_var) as f32;

            CreateNewWP_FromObject(ctx, &mut thiswp);
            i += 1;
        }

        B_TempFree(ctx, 524288); // fileString
        B_TempFree(ctx, 2048); // currentVar

        trap::FS_FCloseFile(ctx.engine, GFsFcloseFileArgs::new(f));

        if (*w).cvars.g_gametype.integer == GT_SIEGE {
            CalculateSiegeGoals(ctx);
        }

        CalculateWeightGoals(ctx);
        // calculate weights for idle activity goals when
        // the bot has absolutely nothing else to do

        CalculateJumpRoutes(ctx);
        // Look at jump points and mark them as requiring
        // force jumping as needed

        1
    }
}

/// Raven `FlagObjects`.
///
/// Finds the waypoint nearest each CTF flag (with a clear box trace) and marks
/// it, latching the `flag*`/`oFlag*`/`eFlag*` globals.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2252-2369`
pub fn FlagObjects(ctx: GameContext<'_>) {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;
        let mut bestindex: c_int = 0;
        let mut found: c_int = 0;
        let mut bestdist: f32 = 999999.0;
        let mut tlen: f32;
        let mut flag_red: *mut gentity_t = core::ptr::null_mut();
        let mut flag_blue: *mut gentity_t = core::ptr::null_mut();
        let mins: vec3_t = [-15.0, -15.0, -5.0];
        let maxs: vec3_t = [15.0, 15.0, 5.0];
        let mut tr: trace_t = core::mem::zeroed();

        while i < (*w).level.num_entities {
            let ent: *mut gentity_t = &mut (*w).entities[i as usize];
            if !ent.is_null() && (*ent).inuse != 0 && !(*ent).classname.is_null() {
                if flag_red.is_null() && c_str_eq((*ent).classname, b"team_CTF_redflag") {
                    flag_red = ent;
                } else if flag_blue.is_null() && c_str_eq((*ent).classname, b"team_CTF_blueflag") {
                    flag_blue = ent;
                }

                if !flag_red.is_null() && !flag_blue.is_null() {
                    break;
                }
            }
            i += 1;
        }

        i = 0;

        if flag_red.is_null() || flag_blue.is_null() {
            return;
        }

        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 {
                let rb = (*flag_red).s.pos.trBase;
                let po = (*p).origin;
                tlen = VectorLength([rb[0] - po[0], rb[1] - po[1], rb[2] - po[2]]);

                if tlen < bestdist {
                    wp_trace(
                        ctx, &mut tr, &rb, &mins, &maxs, &po, (*flag_red).s.number, MASK_SOLID,
                    );

                    if tr.fraction == 1.0 || tr.entityNum as c_int == (*flag_red).s.number {
                        bestdist = tlen;
                        bestindex = i;
                        found = 1;
                    }
                }
            }
            i += 1;
        }

        if found != 0 {
            let p = (*w).globals.gWPArray.0[bestindex as usize];
            (*p).flags |= WPFLAG_RED_FLAG;
            (*w).globals.flagRed = p;
            (*w).globals.oFlagRed = (*w).globals.flagRed;
            (*w).globals.eFlagRed = flag_red;
        }

        bestdist = 999999.0;
        bestindex = 0;
        found = 0;
        i = 0;

        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            if !p.is_null() && (*p).inuse != 0 {
                let bb = (*flag_blue).s.pos.trBase;
                let po = (*p).origin;
                tlen = VectorLength([bb[0] - po[0], bb[1] - po[1], bb[2] - po[2]]);

                if tlen < bestdist {
                    wp_trace(
                        ctx, &mut tr, &bb, &mins, &maxs, &po, (*flag_blue).s.number, MASK_SOLID,
                    );

                    if tr.fraction == 1.0 || tr.entityNum as c_int == (*flag_blue).s.number {
                        bestdist = tlen;
                        bestindex = i;
                        found = 1;
                    }
                }
            }
            i += 1;
        }

        if found != 0 {
            let p = (*w).globals.gWPArray.0[bestindex as usize];
            (*p).flags |= WPFLAG_BLUE_FLAG;
            (*w).globals.flagBlue = p;
            (*w).globals.oFlagBlue = (*w).globals.flagBlue;
            (*w).globals.eFlagBlue = flag_blue;
        }
    }
}

/// `strcmp(s, needle) == 0` on a NUL-terminated C string (exact, case-sensitive).
unsafe fn c_str_eq(s: *const c_char, needle: &[u8]) -> bool {
    if s.is_null() {
        return false;
    }
    core::ffi::CStr::from_ptr(s).to_bytes() == needle
}

/// Raven `SavePathData`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2372-2500`
pub fn SavePathData(ctx: GameContext<'_>, filename: *const c_char) -> c_int {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;

        if (*w).globals.gWPNum == 0 {
            return 0;
        }

        // See `LoadPathData`'s note: `routePath` is a `B_TempAlloc`'d scratch
        // buffer in Raven; kept as an alloc/free pair for bump-allocator
        // stack parity even though we build the path as an owned `String`.
        let _route_path = B_TempAlloc(ctx, 1024);
        let filename_s = cstr_to_str(filename);
        let route_path_s = format!("botroutes/{}.wnt", filename_s);
        B_TempFree(ctx, 1024); // routePath

        let mut f: fileHandle_t = 0;
        trap::FS_FOpenFile(
            ctx.engine,
            GFsFopenFileArgs::new(CString::new(route_path_s).unwrap(), &mut f, FS_WRITE),
        );

        if f == 0 {
            G_Printf(ctx, cstr("^1ERROR: Could not open file to write path data\n").as_ptr());
            return 0;
        }

        if RepairPaths(ctx, QFALSE) == 0 {
            // check if we can see all waypoints from the last. If not, try to branch over.
            trap::FS_FCloseFile(ctx.engine, GFsFcloseFileArgs::new(f));
            return 0;
        }

        CalculatePaths(ctx); // make everything nice and connected before saving

        FlagObjects(ctx); // currently only used for flagging waypoints nearest CTF flags

        let p0 = (*w).globals.gWPArray.0[i as usize];
        let mut file_string = format!(
            "{} {} {} ({} {} {}) {{ ",
            (*p0).index,
            (*p0).flags,
            (*p0).weight,
            (*p0).origin[0],
            (*p0).origin[1],
            (*p0).origin[2],
        );

        // PORT-NOTE(bg-0143): Raven builds `storeString` here for waypoint 0's
        // neighbor list but never concatenates it into `fileString` (only the
        // direct `Com_sprintf` above touches `fileString`) — a genuine Raven
        // bug that silently drops waypoint 0's neighbor list from the saved
        // file. Preserved faithfully per §19/rule 2 (no speculative fixes).
        let mut n: c_int = 0;
        let mut store_string = String::new();
        while n < (*p0).neighbornum {
            let nb = (*p0).neighbors[n as usize];
            if nb.forceJumpTo != 0 {
                store_string = format!("{}{}-{} ", store_string, nb.num, nb.forceJumpTo);
            } else {
                store_string = format!("{}{} ", store_string, nb.num);
            }
            n += 1;
        }

        let p1 = if (i + 1) < MAX_WPARRAY_SIZE {
            (*w).globals.gWPArray.0[(i + 1) as usize]
        } else {
            core::ptr::null_mut()
        };
        let fl_len = if !p1.is_null() && (*p1).inuse != 0 && (*p1).index != 0 {
            let a = [
                (*p0).origin[0] - (*p1).origin[0],
                (*p0).origin[1] - (*p1).origin[1],
                (*p0).origin[2] - (*p1).origin[2],
            ];
            VectorLength(a)
        } else {
            0.0
        };

        (*p0).disttonext = fl_len;

        file_string = format!("{}}} {}\n", file_string, fl_len);

        i += 1;

        while i < (*w).globals.gWPNum {
            let p = (*w).globals.gWPArray.0[i as usize];
            let mut store_string = format!(
                "{} {} {} ({} {} {}) {{ ",
                (*p).index, (*p).flags, (*p).weight, (*p).origin[0], (*p).origin[1], (*p).origin[2],
            );

            let mut n: c_int = 0;
            while n < (*p).neighbornum {
                let nb = (*p).neighbors[n as usize];
                if nb.forceJumpTo != 0 {
                    store_string = format!("{}{}-{} ", store_string, nb.num, nb.forceJumpTo);
                } else {
                    store_string = format!("{}{} ", store_string, nb.num);
                }
                n += 1;
            }

            let pn = if (i + 1) < MAX_WPARRAY_SIZE {
                (*w).globals.gWPArray.0[(i + 1) as usize]
            } else {
                core::ptr::null_mut()
            };
            let fl_len = if !pn.is_null() && (*pn).inuse != 0 && (*pn).index != 0 {
                let a = [
                    (*p).origin[0] - (*pn).origin[0],
                    (*p).origin[1] - (*pn).origin[1],
                    (*p).origin[2] - (*pn).origin[2],
                ];
                VectorLength(a)
            } else {
                0.0
            };

            (*p).disttonext = fl_len;

            store_string = format!("{}}} {}\n", store_string, fl_len);

            file_string.push_str(&store_string);

            i += 1;
        }

        let file_bytes = file_string.as_bytes();
        trap::FS_Write(
            ctx.engine,
            GFsWriteArgs::new(file_bytes.as_ptr(), file_bytes.len() as c_int, f),
        );

        // PORT-NOTE(bg-temp-alloc): Raven's `fileString`/`storeString` are
        // `B_TempAlloc`'d scratch buffers, freed here via `B_TempFree`. We use
        // owned `String`s instead (no B_TempAlloc call), so there is no
        // matching temp-arena allocation to pop — omitting the frees keeps
        // the bump-allocator stack balanced.
        trap::FS_FCloseFile(ctx.engine, GFsFcloseFileArgs::new(f));

        G_Printf(
            ctx,
            cstr("Path data has been saved and updated. You may need to restart the level for some things to be properly calculated.\n")
                .as_ptr(),
        );

        1
    }
}

/// Raven `G_NearestNodeToPoint`.
///
/// Nearest grid node to `point` (read-only; fork-9 by-value).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2510-2541`
pub fn G_NearestNodeToPoint(ctx: GameContext<'_>, point: vec3_t) -> c_int {
    unsafe {
        let w = ctx.world;
        let mut best_index: c_int = -1;
        let mut i: c_int = 0;
        let mut best_dist: f32 = 0.0;
        let mut test_dist: f32;

        while i < (*w).globals.nodenum {
            let o = (*w).globals.nodetable.0[i as usize].origin;
            test_dist = VectorLength([o[0] - point[0], o[1] - point[1], o[2] - point[2]]);

            if best_index == -1 {
                best_index = i;
                best_dist = test_dist;
                i += 1;
                continue;
            }

            if test_dist < best_dist {
                best_index = i;
                best_dist = test_dist;
            }
            i += 1;
        }

        best_index
    }
}

/// Raven `G_NodeClearForNext`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2545-2556`
pub fn G_NodeClearForNext(ctx: GameContext<'_>) {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;
        while i < (*w).globals.nodenum {
            let nt = &mut (*w).globals.nodetable.0[i as usize];
            nt.flags = 0;
            nt.weight = 99999.0;
            i += 1;
        }
    }
}

/// Raven `G_NodeClearFlags`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2558-2568`
pub fn G_NodeClearFlags(ctx: GameContext<'_>) {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;
        while i < (*w).globals.nodenum {
            (*w).globals.nodetable.0[i as usize].flags = 0;
            i += 1;
        }
    }
}

/// Raven `G_NodeMatchingXY`.
///
/// First unflagged node with matching X/Y (exact float compare, per oracle).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2570-2587`
pub fn G_NodeMatchingXY(ctx: GameContext<'_>, x: f32, y: f32) -> c_int {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;
        while i < (*w).globals.nodenum {
            let nt = &(*w).globals.nodetable.0[i as usize];
            if nt.origin[0] == x && nt.origin[1] == y && nt.flags == 0 {
                return i;
            }
            i += 1;
        }
        -1
    }
}

/// Raven `G_NodeMatchingXY_BA`.
///
/// Lowest-weight unflagged node with matching (int-truncated) X/Y, short-circuit
/// returning `final` if reached.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2589-2614`
pub fn G_NodeMatchingXY_BA(ctx: GameContext<'_>, x: c_int, y: c_int, r#final: c_int) -> c_int {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;
        let mut bestindex: c_int = -1;
        let mut best_weight: f32 = 9999.0;

        while i < (*w).globals.nodenum {
            let nt = &(*w).globals.nodetable.0[i as usize];
            if nt.origin[0] as c_int == x
                && nt.origin[1] as c_int == y
                && nt.flags == 0
                && (nt.weight < best_weight || i == r#final)
            {
                if i == r#final {
                    return i;
                }
                bestindex = i;
                best_weight = nt.weight;
            }
            i += 1;
        }

        bestindex
    }
}

/// Raven `G_RecursiveConnection`.
///
/// Flood-fills weights out from `start` across the 4-connected grid until it
/// reaches `end`, optionally requiring a clear trace between adjacent nodes.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2616-2689`
pub fn G_RecursiveConnection(
    ctx: GameContext<'_>,
    start: c_int,
    end: c_int,
    weight: c_int,
    traceCheck: qboolean,
    baseHeight: f32,
) -> c_int {
    unsafe {
        let w = ctx.world;
        // 0 == down, 1 == up, 2 == left, 3 == right
        let mut index_directions: [c_int; 4] = [-1; 4];
        let mut recursive_index: c_int = -1;
        let mut i: c_int = 0;
        let pass_weight = weight + 1;
        let mut given_xy: [f32; 2];

        (*w).globals.nodetable.0[start as usize].weight = pass_weight as f32;

        let sorg = (*w).globals.nodetable.0[start as usize].origin;

        given_xy = [sorg[0] - DEFAULT_GRID_SPACING, sorg[1]];
        index_directions[0] = G_NodeMatchingXY(ctx, given_xy[0], given_xy[1]);

        given_xy = [sorg[0] + DEFAULT_GRID_SPACING, sorg[1]];
        index_directions[1] = G_NodeMatchingXY(ctx, given_xy[0], given_xy[1]);

        given_xy = [sorg[0], sorg[1] - DEFAULT_GRID_SPACING];
        index_directions[2] = G_NodeMatchingXY(ctx, given_xy[0], given_xy[1]);

        given_xy = [sorg[0], sorg[1] + DEFAULT_GRID_SPACING];
        index_directions[3] = G_NodeMatchingXY(ctx, given_xy[0], given_xy[1]);

        i = 0;
        while i < 4 {
            let d = index_directions[i as usize];
            if d == end {
                // connected all the way to the destination
                return d;
            }

            if d != -1 && (*w).globals.nodetable.0[d as usize].flags != 0 {
                // already used — not valid
                index_directions[i as usize] = -1;
            } else if d != -1 {
                // otherwise mark it as used
                (*w).globals.nodetable.0[d as usize].flags = 1;
            }

            let d = index_directions[i as usize];
            if d != -1 && traceCheck != 0 {
                let mut tr: trace_t = core::mem::zeroed();
                let a = (*w).globals.nodetable.0[start as usize].origin;
                let b = (*w).globals.nodetable.0[d as usize].origin;
                wp_trace(
                    ctx, &mut tr, &a, core::ptr::null(), core::ptr::null(), &b,
                    ENTITYNUM_NONE, CONTENTS_SOLID,
                );
                if tr.fraction != 1.0 {
                    index_directions[i as usize] = -1;
                }
            }

            let d = index_directions[i as usize];
            if d != -1 {
                // still valid — keep connecting via this point
                recursive_index = G_RecursiveConnection(ctx, d, end, pass_weight, traceCheck, baseHeight);
            }

            if recursive_index != -1 {
                return recursive_index;
            }

            i += 1;
        }

        recursive_index
    }
}

/// Raven `G_BackwardAttachment`.
///
/// After a node path exists, walks it back toward `finalDestination` (lowest
/// weight per step), materialising waypoints via `CreateNewWP_InsertUnder`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:2981-3048`
pub fn G_BackwardAttachment(
    ctx: GameContext<'_>,
    start: c_int,
    finalDestination: c_int,
    insertAfter: c_int,
) -> qboolean {
    unsafe {
        let w = ctx.world;
        let mut index_directions: [c_int; 4] = [-1; 4];
        let mut i: c_int = 0;
        let mut lowest_weight: c_int = 9999;
        let mut desired_index: c_int = -1;

        let sorg = (*w).globals.nodetable.0[start as usize].origin;

        let mut given_xy: [f32; 2] = [sorg[0] - DEFAULT_GRID_SPACING, sorg[1]];
        index_directions[0] =
            G_NodeMatchingXY_BA(ctx, given_xy[0] as c_int, given_xy[1] as c_int, finalDestination);

        given_xy = [sorg[0] + DEFAULT_GRID_SPACING, sorg[1]];
        index_directions[1] =
            G_NodeMatchingXY_BA(ctx, given_xy[0] as c_int, given_xy[1] as c_int, finalDestination);

        given_xy = [sorg[0], sorg[1] - DEFAULT_GRID_SPACING];
        index_directions[2] =
            G_NodeMatchingXY_BA(ctx, given_xy[0] as c_int, given_xy[1] as c_int, finalDestination);

        given_xy = [sorg[0], sorg[1] + DEFAULT_GRID_SPACING];
        index_directions[3] =
            G_NodeMatchingXY_BA(ctx, given_xy[0] as c_int, given_xy[1] as c_int, finalDestination);

        while i < 4 {
            let d = index_directions[i as usize];
            if d != -1 {
                if d == finalDestination {
                    // found the original point and linked all the way back
                    let a = (*w).globals.nodetable.0[start as usize].origin;
                    CreateNewWP_InsertUnder(ctx, a, 0, insertAfter);
                    let b = (*w).globals.nodetable.0[d as usize].origin;
                    CreateNewWP_InsertUnder(ctx, b, 0, insertAfter);
                    return QTRUE;
                }

                let nt = &(*w).globals.nodetable.0[d as usize];
                if nt.weight < lowest_weight as f32 && nt.weight != 0.0 && nt.flags == 0 {
                    desired_index = d;
                    lowest_weight = nt.weight as c_int;
                }
            }
            i += 1;
        }

        if desired_index != -1 {
            // create a waypoint here, then recurse for the lowest-weight neighbor
            if (*w).globals.gWPNum < 3900 {
                let a = (*w).globals.nodetable.0[start as usize].origin;
                CreateNewWP_InsertUnder(ctx, a, 0, insertAfter);
            } else {
                return QFALSE;
            }

            (*w).globals.nodetable.0[start as usize].flags = 1;
            return G_BackwardAttachment(ctx, desired_index, finalDestination, insertAfter);
        }

        QFALSE
    }
}

/// Raven `G_RMGPathing`.
///
/// Generate waypoint information on-the-fly for the random mission.
///
/// The `PATH_TIME_DEBUG`/`ASCII_ART_DEBUG`/`PAINFULLY_DEBUGGING_THROUGH_VM`
/// `#ifdef` blocks are not defined in this build (dead debug source); dropped
/// per §20/ruling 11, including their `trap_Milliseconds`/`Com_Printf` calls.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:3055-3250`
pub fn G_RMGPathing(ctx: GameContext<'_>) {
    // `DEFAULT_MINS_2`/`DEFAULT_MAXS_2` (`bg_public.h:41-42`), file-local per
    // this file's convention (cf. `MASK_PLAYERSOLID`).
    const DEFAULT_MINS_2: f32 = -24.0;
    const DEFAULT_MAXS_2: f32 = 40.0;

    unsafe {
        let w = ctx.world;

        let terrain = G_Find(
            ctx,
            core::ptr::null_mut(),
            core::mem::offset_of!(gentity_t, classname) as c_int,
            c"terrain".as_ptr(),
        );

        let et_terrain = mp_bg::public::entity_type::entityType_t::ET_TERRAIN as c_int;

        if terrain.is_null() || (*terrain).inuse == 0 || (*terrain).s.eType != et_terrain {
            G_Printf(ctx, cstr("Error: RMG with no terrain!\n").as_ptr());
            return;
        }

        (*w).globals.nodenum = 0;
        for i in 0..MAX_NODETABLE_SIZE as usize {
            (*w).globals.nodetable.0[i] = core::mem::zeroed();
        }

        let tr_mins: vec3_t = [-15.0, -15.0, DEFAULT_MINS_2];
        let tr_maxs: vec3_t = [15.0, 15.0, DEFAULT_MAXS_2];

        let mut place_x = (*terrain).r.absmin[0];
        let mut place_y = (*terrain).r.absmin[1];
        let place_z = (*terrain).r.absmax[2] - 400.0;
        let grid_spacing = DEFAULT_GRID_SPACING;

        // skim through the entirety of the terrain limits and drop nodes, removing
        // nodes that start in solid or fall too high on the terrain.
        while place_y < (*terrain).r.absmax[1] {
            if (*w).globals.nodenum >= MAX_NODETABLE_SIZE {
                break;
            }

            while place_x < (*terrain).r.absmax[0] {
                if (*w).globals.nodenum >= MAX_NODETABLE_SIZE {
                    break;
                }

                let n = (*w).globals.nodenum as usize;
                (*w).globals.nodetable.0[n].origin = [place_x, place_y, place_z];

                let mut down_vec = (*w).globals.nodetable.0[n].origin;
                down_vec[2] -= 3000.0;

                let mut tr: trace_t = core::mem::zeroed();
                wp_trace(
                    ctx,
                    &mut tr,
                    &(*w).globals.nodetable.0[n].origin,
                    &tr_mins,
                    &tr_maxs,
                    &down_vec,
                    ENTITYNUM_NONE,
                    MASK_SOLID,
                );

                if (tr.entityNum >= ENTITYNUM_WORLD
                    || (*w).entities[tr.entityNum as usize].s.eType == et_terrain)
                    && tr.endpos[2] < (*terrain).r.absmin[2] + 750.0
                {
                    // only drop nodes on terrain directly
                    (*w).globals.nodetable.0[n].origin = tr.endpos;
                    (*w).globals.nodenum += 1;
                } else {
                    (*w).globals.nodetable.0[n].origin = [0.0, 0.0, 0.0];
                }

                place_x += grid_spacing;
            }

            place_x = (*terrain).r.absmin[0];
            place_y += grid_spacing;
        }

        G_NodeClearForNext(ctx);

        // The grid has been placed down, now use it to connect the points in the level.
        let mut i: c_int = 0;
        while i < (*w).globals.gSpawnPointNum - 1 {
            let sp0 = (*w).globals.gSpawnPoints.0[i as usize];
            let sp1 = (*w).globals.gSpawnPoints.0[(i + 1) as usize];

            if sp0.is_null() || (*sp0).inuse == 0 || sp1.is_null() || (*sp1).inuse == 0 {
                i += 1;
                continue;
            }

            let nearest_index = G_NearestNodeToPoint(ctx, (*sp0).s.origin);
            let nearest_index_for_next = G_NearestNodeToPoint(ctx, (*sp1).s.origin);

            if nearest_index == -1 || nearest_index_for_next == -1 {
                // Looks like there is no grid data near one of the points. Ideally, this will never happen.
                i += 1;
                continue;
            }

            if nearest_index == nearest_index_for_next {
                // Two spawn points on top of each other? We don't need to do both points, keep going until the next differs.
                i += 1;
                continue;
            }

            // So, nearestIndex is now the node for the spawn point we're on, and nearestIndexForNext is the
            // node we want to get to from here.

            // For now I am going to branch out mindlessly, but I will probably want to use some sort of A* algorithm
            // here to lessen the time taken.
            if G_RecursiveConnection(ctx, nearest_index, nearest_index_for_next, 0, QTRUE, (*terrain).r.absmin[2])
                != nearest_index_for_next
            {
                // failed to branch to where we want. Oh well, try it without trace checks.
                G_NodeClearForNext(ctx);

                if G_RecursiveConnection(
                    ctx,
                    nearest_index,
                    nearest_index_for_next,
                    0,
                    QFALSE,
                    (*terrain).r.absmin[2],
                ) != nearest_index_for_next
                {
                    // still failed somehow. Just disregard this point.
                    G_NodeClearForNext(ctx);
                    i += 1;
                    continue;
                }
            }

            // Now our node array is set up so that highest reasonable weight is the destination node, and 2 is next to the original index,
            // so trace back to that point.
            G_NodeClearFlags(ctx);

            if G_BackwardAttachment(ctx, nearest_index_for_next, nearest_index, (*w).globals.gWPNum - 1) != 0 {
                // successfully connected the trail from nearestIndex to nearestIndexForNext
                if (*sp1).inuse != 0 && !(*sp1).item.is_null() && (*(*sp1).item).giType == IT_TEAM {
                    // This point is actually a CTF flag.
                    if (*(*sp1).item).giTag == PW_REDFLAG || (*(*sp1).item).giTag == PW_BLUEFLAG {
                        // Place a waypoint on the flag next in the trail, so the nearest grid point will link to it.
                        CreateNewWP_InsertUnder(ctx, (*sp1).s.origin, WPFLAG_NEVERONEWAY, (*w).globals.gWPNum - 1);
                    }
                }
            } else {
                break;
            }

            G_NodeClearForNext(ctx);
            i += 1;
        }

        RepairPaths(ctx, QTRUE); // this has different behaviour for RMG and will just flag all points one way that don't trace to each other.
    }
}

/// Raven `BeginAutoPathRoutine`.
///
/// Called for RMG levels. The `PAINFULLY_DEBUGGING_THROUGH_VM` `#ifdef`
/// `Com_Printf` blocks are dead source in this build (not defined); dropped
/// per §20/ruling 11.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:3254-3342`
pub fn BeginAutoPathRoutine(ctx: GameContext<'_>) {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;

        (*w).globals.gSpawnPointNum = 0;

        CreateNewWP(ctx, crate::q_math::vec3_origin, 0); // create a dummy waypoint to insert under

        while i < (*w).level.num_entities {
            let ent: *mut gentity_t = &mut (*w).entities[i as usize];

            if !ent.is_null()
                && (*ent).inuse != 0
                && !(*ent).classname.is_null()
                && *(*ent).classname != 0
                && Q_stricmp((*ent).classname, c"info_player_deathmatch".as_ptr()) == 0
            {
                if (*ent).s.origin[2] < 1280.0 {
                    // h4x
                    let n = (*w).globals.gSpawnPointNum as usize;
                    (*w).globals.gSpawnPoints.0[n] = ent;
                    (*w).globals.gSpawnPointNum += 1;
                }
            } else if !ent.is_null()
                && (*ent).inuse != 0
                && !(*ent).item.is_null()
                && (*(*ent).item).giType == IT_TEAM
                && ((*(*ent).item).giTag == PW_REDFLAG || (*(*ent).item).giTag == PW_BLUEFLAG)
            {
                // also make it path to flags in CTF.
                let n = (*w).globals.gSpawnPointNum as usize;
                (*w).globals.gSpawnPoints.0[n] = ent;
                (*w).globals.gSpawnPointNum += 1;
            }

            i += 1;
        }

        if (*w).globals.gSpawnPointNum < 1 {
            return;
        }

        G_RMGPathing(ctx);

        // rww - Using a faster in-engine version because we're having to wait for this stuff to get done as opposed to just saving it once.
        trap::Bot_UpdateWaypoints(
            ctx.engine,
            GBotUpdatewaypointsArgs::new(
                (*w).globals.gWPNum,
                (*w).globals.gWPArray.0.as_mut_ptr() as *mut *mut c_void,
            ),
        );
        trap::Bot_CalculatePaths(ctx.engine, GBotCalculatepathsArgs::new((*w).cvars.g_RMG.integer));
        // CalculatePaths(); //make everything nice and connected

        FlagObjects(ctx); // currently only used for flagging waypoints nearest CTF flags

        i = 0;

        while i < (*w).globals.gWPNum - 1 {
            // disttonext is normally set on save, and when a file is loaded. For RMG we must do it after calc'ing.
            let p = (*w).globals.gWPArray.0[i as usize];
            let pn = (*w).globals.gWPArray.0[(i + 1) as usize];
            let v = [
                (*p).origin[0] - (*pn).origin[0],
                (*p).origin[1] - (*pn).origin[1],
                (*p).origin[2] - (*pn).origin[2],
            ];
            (*p).disttonext = VectorLength(v);
            i += 1;
        }

        RemoveWP(ctx); // remove the dummy point at the end of the trail
    }
}

/// Raven `LoadPath_ThisLevel`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:3347-3423`
pub fn LoadPath_ThisLevel(ctx: GameContext<'_>) {
    unsafe {
        let w = ctx.world;
        let mut i: c_int = 0;

        let mut mapname: vmCvar_t = vmCvar_t::zeroed();
        // PORT-NOTE(missing-const): `CVAR_SERVERINFO`/`CVAR_ROM`/`CVAR_CHEAT`
        // bit constants have no ported home yet (same class of gap noted at
        // `g_bot.rs:361`; missing_symbols).
        trap::Cvar_Register(
            ctx.engine,
            GCvarRegisterArgs::new(
                &mut mapname as *mut vmCvar_t,
                CString::new("mapname").unwrap(),
                CString::new("").unwrap(),
                CVAR_SERVERINFO | CVAR_ROM,
            ),
        );

        if (*w).cvars.g_RMG.integer != 0 {
            // If RMG, generate the path on-the-fly
            // PORT-NOTE(cvar-placement): `bot_normgpath` is an `ai_wpnav.c`
            // file-scope `vmCvar_t` with no home in `GameCvars` yet
            // (missing_symbols); this is disabled for now per the oracle
            // comment (standard bot nav on premade terrain levels).
            trap::Cvar_Register(
                ctx.engine,
                GCvarRegisterArgs::new(
                    &mut (*w).cvars.bot_normgpath as *mut vmCvar_t,
                    CString::new("bot_normgpath").unwrap(),
                    CString::new("1").unwrap(),
                    CVAR_CHEAT,
                ),
            );
            // note: This is disabled for now as I'm using standard bot nav
            // on premade terrain levels.

            if (*w).cvars.bot_normgpath.integer == 0 {
                // autopath the random map
                BeginAutoPathRoutine(ctx);
            } else {
                // try loading standard nav data
                LoadPathData(ctx, mapname.string.as_ptr());
            }

            (*w).globals.gLevelFlags |= LEVELFLAG_NOPOINTPREDICTION;
        } else {
            if LoadPathData(ctx, mapname.string.as_ptr()) == 2 {
                // enter "edit" mode if cheats enabled?
            }
        }

        // PORT-NOTE(cvar-placement): `bot_wp_edit` has no home in
        // `GameCvars` yet (missing_symbols).
        trap::Cvar_Update(
            ctx.engine,
            GCvarUpdateArgs::new(&mut (*w).cvars.bot_wp_edit as *mut vmCvar_t),
        );

        if (*w).cvars.bot_wp_edit.value != 0.0 {
            (*w).globals.gBotEdit = 1.0;
        } else {
            (*w).globals.gBotEdit = 0.0;
        }

        // set the flag entities
        while i < (*w).level.num_entities {
            let ent: *mut gentity_t = &mut (*w).entities[i as usize];

            if !ent.is_null() && (*ent).inuse != 0 && !(*ent).classname.is_null() {
                if (*w).globals.eFlagRed.is_null() && c_str_eq((*ent).classname, b"team_CTF_redflag") {
                    (*w).globals.eFlagRed = ent;
                } else if (*w).globals.eFlagBlue.is_null() && c_str_eq((*ent).classname, b"team_CTF_blueflag") {
                    (*w).globals.eFlagBlue = ent;
                }

                if !(*w).globals.eFlagRed.is_null() && !(*w).globals.eFlagBlue.is_null() {
                    break;
                }
            }

            i += 1;
        }
    }
}

/// Raven `GetClosestSpawn`.
///
/// Nearest spawn entity to `ent`'s player origin (walks only the non-client
/// entity range).
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:3425-3457`
pub fn GetClosestSpawn(ctx: GameContext<'_>, ent: *mut gentity_t) -> *mut gentity_t {
    unsafe {
        let w = ctx.world;
        let mut closest_spawn: *mut gentity_t = core::ptr::null_mut();
        let mut closest_dist: f32 = -1.0;
        let mut i: c_int = MAX_CLIENTS as c_int;

        while i < (*w).level.num_entities {
            let spawn: *mut gentity_t = &mut (*w).entities[i as usize];
            if !spawn.is_null()
                && (*spawn).inuse != 0
                && (Q_stricmp((*spawn).classname, c"info_player_start".as_ptr()) == 0
                    || Q_stricmp((*spawn).classname, c"info_player_deathmatch".as_ptr()) == 0)
            {
                let eo = (*((*ent).client as *mut gclient_t)).ps.origin;
                let so = (*spawn).r.currentOrigin;
                let check_dist = VectorLength([eo[0] - so[0], eo[1] - so[1], eo[2] - so[2]]);

                if closest_dist == -1.0 || check_dist < closest_dist {
                    closest_spawn = spawn;
                    closest_dist = check_dist;
                }
            }
            i += 1;
        }

        closest_spawn
    }
}

/// Raven `GetNextSpawnInIndex`.
///
/// Next spawn entity after `currentSpawn` in index order, wrapping back to
/// `MAX_CLIENTS` if none follows.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:3459-3499`
pub fn GetNextSpawnInIndex(
    ctx: GameContext<'_>,
    currentSpawn: *mut gentity_t,
) -> *mut gentity_t {
    unsafe {
        let w = ctx.world;
        let mut next_spawn: *mut gentity_t = core::ptr::null_mut();
        let mut i: c_int = (*currentSpawn).s.number + 1;

        while i < (*w).level.num_entities {
            let spawn: *mut gentity_t = &mut (*w).entities[i as usize];
            if !spawn.is_null()
                && (*spawn).inuse != 0
                && (Q_stricmp((*spawn).classname, c"info_player_start".as_ptr()) == 0
                    || Q_stricmp((*spawn).classname, c"info_player_deathmatch".as_ptr()) == 0)
            {
                next_spawn = spawn;
                break;
            }
            i += 1;
        }

        if next_spawn.is_null() {
            // loop back around to 0 (client range end)
            i = MAX_CLIENTS as c_int;
            while i < (*w).level.num_entities {
                let spawn: *mut gentity_t = &mut (*w).entities[i as usize];
                if !spawn.is_null()
                    && (*spawn).inuse != 0
                    && (Q_stricmp((*spawn).classname, c"info_player_start".as_ptr()) == 0
                        || Q_stricmp((*spawn).classname, c"info_player_deathmatch".as_ptr()) == 0)
                {
                    next_spawn = spawn;
                    break;
                }
                i += 1;
            }
        }

        next_spawn
    }
}

/// Raven `AcceptBotCommand`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:3501-3813`
pub fn AcceptBotCommand(ctx: GameContext<'_>, cmd: *mut c_char, pl: *mut gentity_t) -> c_int {
    unsafe {
        let w = ctx.world;

        if (*w).globals.gBotEdit == 0.0 {
            return 0;
        }

        let mut optional_argument: c_int = 0;
        let mut i: c_int = 0;
        let mut flags_from_argument: c_int = 0;
        let mut optional_s_argument: *mut c_char = core::ptr::null_mut();
        let mut required_s_argument: *mut c_char = core::ptr::null_mut();

        // if a waypoint editing related command is issued, bots will deactivate.
        // once bot_wp_save is issued and the trail is recalculated, bots will activate again.

        if pl.is_null() || (*pl).client.is_null() {
            return 0;
        }

        if Q_stricmp(cmd, c"bot_wp_cmdlist".as_ptr()) == 0 {
            // lists all the bot waypoint commands.
            G_Printf(ctx, cstr("^3bot_wp_add^7 - Add a waypoint (optional int parameter will insert the point after the specified waypoint index in a trail)\n\n").as_ptr());
            G_Printf(ctx, cstr("^3bot_wp_rem^7 - Remove a waypoint (removes last unless waypoint index is specified as a parameter)\n\n").as_ptr());
            G_Printf(ctx, cstr("^3bot_wp_addflagged^7 - Same as wp_add, but adds a flagged point (type bot_wp_addflagged for help)\n\n").as_ptr());
            G_Printf(ctx, cstr("^3bot_wp_switchflags^7 - Switches flags on an existing waypoint (type bot_wp_switchflags for help)\n\n").as_ptr());
            G_Printf(ctx, cstr("^3bot_wp_tele^7 - Teleport yourself to the specified waypoint's location\n").as_ptr());
            G_Printf(ctx, cstr("^3bot_wp_killoneways^7 - Removes oneway (backward and forward) flags on all waypoints in the level\n\n").as_ptr());
            G_Printf(ctx, cstr("^3bot_wp_save^7 - Saves all waypoint data into a file for later use\n").as_ptr());

            return 1;
        }

        if Q_stricmp(cmd, c"bot_wp_add".as_ptr()) == 0 {
            (*w).globals.gDeactivated = 1.0;
            optional_s_argument = ConcatArgs(ctx, 1);

            if !optional_s_argument.is_null() {
                optional_argument = crate::bg_lib::atoi(optional_s_argument);
            }

            if !optional_s_argument.is_null() && *optional_s_argument != 0 {
                CreateNewWP_InTrail(
                    ctx,
                    (*((*pl).client as *mut gclient_t)).ps.origin,
                    0,
                    optional_argument,
                );
            } else {
                CreateNewWP(ctx, (*((*pl).client as *mut gclient_t)).ps.origin, 0);
            }
            return 1;
        }

        if Q_stricmp(cmd, c"bot_wp_rem".as_ptr()) == 0 {
            (*w).globals.gDeactivated = 1.0;

            optional_s_argument = ConcatArgs(ctx, 1);

            if !optional_s_argument.is_null() {
                optional_argument = crate::bg_lib::atoi(optional_s_argument);
            }

            if !optional_s_argument.is_null() && *optional_s_argument != 0 {
                RemoveWP_InTrail(ctx, optional_argument);
            } else {
                RemoveWP(ctx);
            }

            return 1;
        }

        if Q_stricmp(cmd, c"bot_wp_tele".as_ptr()) == 0 {
            (*w).globals.gDeactivated = 1.0;
            optional_s_argument = ConcatArgs(ctx, 1);

            if !optional_s_argument.is_null() {
                optional_argument = crate::bg_lib::atoi(optional_s_argument);
            }

            if !optional_s_argument.is_null() && *optional_s_argument != 0 {
                TeleportToWP(ctx, pl, optional_argument);
            } else {
                G_Printf(ctx, cstr("^3You didn't specify an index. Assuming last.\n").as_ptr());
                TeleportToWP(ctx, pl, (*w).globals.gWPNum - 1);
            }
            return 1;
        }

        if Q_stricmp(cmd, c"bot_wp_spawntele".as_ptr()) == 0 {
            let mut closest_spawn = GetClosestSpawn(ctx, pl);

            if closest_spawn.is_null() {
                // There should always be a spawn point..
                return 1;
            }

            closest_spawn = GetNextSpawnInIndex(ctx, closest_spawn);

            if !closest_spawn.is_null() {
                (*((*pl).client as *mut gclient_t)).ps.origin = (*closest_spawn).r.currentOrigin;
            }
            return 1;
        }

        if Q_stricmp(cmd, c"bot_wp_addflagged".as_ptr()) == 0 {
            (*w).globals.gDeactivated = 1.0;

            required_s_argument = ConcatArgs(ctx, 1);

            if required_s_argument.is_null() || *required_s_argument == 0 {
                G_Printf(ctx, cstr("^3Flag string needed for bot_wp_addflagged\nj - Jump point\nd - Duck point\nc - Snipe or camp standing\nf - Wait for func\nm - Do not move to when func is under\ns - Snipe or camp\nx - Oneway, forward\ny - Oneway, back\ng - Mission goal\nn - No visibility\nExample (for a point the bot would jump at, and reverse on when traveling a trail backwards):\nbot_wp_addflagged jx\n").as_ptr());
                return 1;
            }

            while *required_s_argument.offset(i as isize) != 0 {
                let c = *required_s_argument.offset(i as isize);
                if c == b'j' as c_char {
                    flags_from_argument |= WPFLAG_JUMP;
                } else if c == b'd' as c_char {
                    flags_from_argument |= WPFLAG_DUCK;
                } else if c == b'c' as c_char {
                    flags_from_argument |= WPFLAG_SNIPEORCAMPSTAND;
                } else if c == b'f' as c_char {
                    flags_from_argument |= WPFLAG_WAITFORFUNC;
                } else if c == b's' as c_char {
                    flags_from_argument |= WPFLAG_SNIPEORCAMP;
                } else if c == b'x' as c_char {
                    flags_from_argument |= WPFLAG_ONEWAY_FWD;
                } else if c == b'y' as c_char {
                    flags_from_argument |= WPFLAG_ONEWAY_BACK;
                } else if c == b'g' as c_char {
                    flags_from_argument |= WPFLAG_GOALPOINT;
                } else if c == b'n' as c_char {
                    flags_from_argument |= WPFLAG_NOVIS;
                } else if c == b'm' as c_char {
                    flags_from_argument |= WPFLAG_NOMOVEFUNC;
                }

                i += 1;
            }

            optional_s_argument = ConcatArgs(ctx, 2);

            if !optional_s_argument.is_null() {
                optional_argument = crate::bg_lib::atoi(optional_s_argument);
            }

            if !optional_s_argument.is_null() && *optional_s_argument != 0 {
                CreateNewWP_InTrail(
                    ctx,
                    (*((*pl).client as *mut gclient_t)).ps.origin,
                    flags_from_argument,
                    optional_argument,
                );
            } else {
                CreateNewWP(ctx, (*((*pl).client as *mut gclient_t)).ps.origin, flags_from_argument);
            }
            return 1;
        }

        if Q_stricmp(cmd, c"bot_wp_switchflags".as_ptr()) == 0 {
            (*w).globals.gDeactivated = 1.0;

            required_s_argument = ConcatArgs(ctx, 1);

            if required_s_argument.is_null() || *required_s_argument == 0 {
                G_Printf(ctx, cstr("^3Flag string needed for bot_wp_switchflags\nType bot_wp_addflagged for a list of flags and their corresponding characters, or use 0 for no flags.\nSyntax: bot_wp_switchflags <flags> <n>\n").as_ptr());
                return 1;
            }

            while *required_s_argument.offset(i as isize) != 0 {
                let c = *required_s_argument.offset(i as isize);
                if c == b'j' as c_char {
                    flags_from_argument |= WPFLAG_JUMP;
                } else if c == b'd' as c_char {
                    flags_from_argument |= WPFLAG_DUCK;
                } else if c == b'c' as c_char {
                    flags_from_argument |= WPFLAG_SNIPEORCAMPSTAND;
                } else if c == b'f' as c_char {
                    flags_from_argument |= WPFLAG_WAITFORFUNC;
                } else if c == b's' as c_char {
                    flags_from_argument |= WPFLAG_SNIPEORCAMP;
                } else if c == b'x' as c_char {
                    flags_from_argument |= WPFLAG_ONEWAY_FWD;
                } else if c == b'y' as c_char {
                    flags_from_argument |= WPFLAG_ONEWAY_BACK;
                } else if c == b'g' as c_char {
                    flags_from_argument |= WPFLAG_GOALPOINT;
                } else if c == b'n' as c_char {
                    flags_from_argument |= WPFLAG_NOVIS;
                } else if c == b'm' as c_char {
                    flags_from_argument |= WPFLAG_NOMOVEFUNC;
                }

                i += 1;
            }

            optional_s_argument = ConcatArgs(ctx, 2);

            if !optional_s_argument.is_null() {
                optional_argument = crate::bg_lib::atoi(optional_s_argument);
            }

            if !optional_s_argument.is_null() && *optional_s_argument != 0 {
                WPFlagsModify(ctx, optional_argument, flags_from_argument);
            } else {
                G_Printf(ctx, cstr("^3Waypoint number (to modify) needed for bot_wp_switchflags\nSyntax: bot_wp_switchflags <flags> <n>\n").as_ptr());
            }
            return 1;
        }

        if Q_stricmp(cmd, c"bot_wp_killoneways".as_ptr()) == 0 {
            i = 0;

            while i < (*w).globals.gWPNum {
                let p = (*w).globals.gWPArray.0[i as usize];
                if !p.is_null() && (*p).inuse != 0 {
                    if (*p).flags & WPFLAG_ONEWAY_FWD != 0 {
                        (*p).flags -= WPFLAG_ONEWAY_FWD;
                    }
                    if (*p).flags & WPFLAG_ONEWAY_BACK != 0 {
                        (*p).flags -= WPFLAG_ONEWAY_BACK;
                    }
                }

                i += 1;
            }

            return 1;
        }

        if Q_stricmp(cmd, c"bot_wp_save".as_ptr()) == 0 {
            (*w).globals.gDeactivated = 0.0;
            let mut mapname: vmCvar_t = vmCvar_t::zeroed();
            // PORT-NOTE(missing-const): `CVAR_SERVERINFO`/`CVAR_ROM` bit
            // constants have no ported home yet (missing_symbols).
            trap::Cvar_Register(
                ctx.engine,
                GCvarRegisterArgs::new(
                    &mut mapname as *mut vmCvar_t,
                    CString::new("mapname").unwrap(),
                    CString::new("").unwrap(),
                    CVAR_SERVERINFO | CVAR_ROM,
                ),
            );
            SavePathData(ctx, mapname.string.as_ptr());
            return 1;
        }

        0
    }
}
